/**
 * agente.js — Motor de planificación de OptiRuta-Agent (Capa 2)
 * Trabajo Final MBA UCEMA — v1.1
 *
 * QUÉ ES Y QUÉ NO ES:
 * Este archivo NO invoca un LLM. Es el motor determinista que ejecuta el contrato
 * de prompts/system_prompt.md: geocodifica, arma la matriz de tiempos, secuencia,
 * calcula ETAs y clasifica el nivel de supervisión L0–L4. La capa de LLM
 * (Modo A, ver README §6) es la que interpreta pedidos en lenguaje natural y
 * llama a este motor. Ver DECISIONES.md §5 para por qué quedó así.
 *
 * Herramientas externas reales que usa:
 *   - Nominatim (OpenStreetMap) para geocodificar direcciones no cacheadas.
 *   - OSRM /table para la matriz de duraciones y distancias viales (1 sola llamada).
 * Ambas se registran en meta_ejecucion.fuentes: la salida siempre dice de dónde
 * salió cada número. Si la red falla, se degrada a Haversine @25 km/h y lo declara.
 *
 * Uso:
 *   node agente.js <entrada.csv> <salida.json> [--inicio=HH:MM] [--deposito="..."]
 *                  [--base-url=http://localhost:8000] [--sin-red]
 *
 * Ejemplo:
 *   node agente.js jornada_hoy.csv output.json --inicio=08:30
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { validarContraContrato } = require('./validador');

// ---------------------------------------------------------------------------
// Parámetros del contrato (prompts/system_prompt.md §5)
// ---------------------------------------------------------------------------
const VERSION_AGENTE = '1.1';
const LIMITE_JORNADA_MIN = 480;      // 8 horas
const UMBRAL_AUTONOMIA_MIN = 420;    // < 7 h ⇒ candidato a L0
const VELOCIDAD_URBANA_KMH = 25;     // fallback declarado
const ATENCION_ESTANDAR_MIN = 15;
const ATENCION_PESADA_MIN = 30;
const TIMEOUT_RED_MS = 8000;         // v1.0 usaba 200 ms y por eso OSRM nunca respondía
const PAUSA_NOMINATIM_MS = 1100;     // política de uso de Nominatim: máx. 1 req/s
const USER_AGENT = 'OptiRuta-Agent/1.1 (MBA UCEMA - trabajo final; contacto via repositorio)';
const PENALIDAD_VENTANA_MIN = 600;   // costo de secuenciación por violar una ventana

// Caja geográfica AMBA: coordenada fuera de acá es geocodificación no confiable.
const BBOX_AMBA = { latMin: -34.90, latMax: -34.40, lngMin: -58.80, lngMax: -58.20 };

const CACHE_PATH = path.join(__dirname, '.geocache.json');
const CACHE_TTL_DIAS = 90;             // política de retención de la caché de geocodificación
const TRACKING_VIGENCIA_HS = 24;       // vida útil del enlace de seguimiento del cliente

// Coordenadas verificadas a mano (evita pegarle a Nominatim en cada corrida).
const COORDS_CONOCIDAS = {
  'av. callao 1000':     { lat: -34.5975, lng: -58.3930 },
  'av. santa fe 3200':   { lat: -34.5878, lng: -58.4110 },
  'av. córdoba 3900':    { lat: -34.5945, lng: -58.4230 },
  'av. cabildo 2000':    { lat: -34.5610, lng: -58.4560 },
  'juana manso 1100':    { lat: -34.6140, lng: -58.3630 },
  'defensa 800':         { lat: -34.6180, lng: -58.3740 },
  'av. las heras 2100':  { lat: -34.5890, lng: -58.3950 },
  'av. rivadavia 5100':  { lat: -34.6190, lng: -58.4380 },
  'av. directorio 1800': { lat: -34.6330, lng: -58.4550 },
  'av. medrano 600':     { lat: -34.6060, lng: -58.4190 },
  'florida 1000':        { lat: -34.5960, lng: -58.3750 }
};

const DEPOSITO_POR_DEFECTO = 'Av. Callao 1000, Buenos Aires, Argentina';

// ---------------------------------------------------------------------------
// Utilidades
// ---------------------------------------------------------------------------
function parsearArgs(argv) {
  const posicionales = [];
  const opciones = { inicio: '08:30', deposito: DEPOSITO_POR_DEFECTO, baseUrl: 'http://localhost:8000', sinRed: false };
  for (const arg of argv) {
    if (arg === '--sin-red') opciones.sinRed = true;
    else if (arg.startsWith('--inicio=')) opciones.inicio = arg.slice(9);
    else if (arg.startsWith('--deposito=')) opciones.deposito = arg.slice(11);
    else if (arg.startsWith('--base-url=')) opciones.baseUrl = arg.slice(11);
    else posicionales.push(arg);
  }
  opciones.entrada = posicionales[0] || 'jornada_hoy.csv';
  opciones.salida = posicionales[1] || 'output.json';
  return opciones;
}

function hhmmAMinutos(hhmm) {
  const m = /^(\d{1,2}):(\d{2})$/.exec((hhmm || '').trim());
  if (!m) return null;
  return parseInt(m[1], 10) * 60 + parseInt(m[2], 10);
}

function minutosAHhmm(minutos) {
  const m = ((minutos % 1440) + 1440) % 1440;
  return `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
}

function parsearVentana(texto) {
  const m = /^\s*(\d{1,2}:\d{2})\s*-\s*(\d{1,2}:\d{2})\s*$/.exec(texto || '');
  if (!m) return { inicio: null, fin: null, texto: texto || '' };
  return { inicio: hhmmAMinutos(m[1]), fin: hhmmAMinutos(m[2]), texto: `${m[1]}-${m[2]}` };
}

function distanciaHaversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 +
            Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function dentroDelAMBA(lat, lng) {
  return lat >= BBOX_AMBA.latMin && lat <= BBOX_AMBA.latMax &&
         lng >= BBOX_AMBA.lngMin && lng <= BBOX_AMBA.lngMax;
}

const esperar = ms => new Promise(r => setTimeout(r, ms));

async function fetchConTimeout(url, opciones = {}) {
  const controlador = new AbortController();
  const id = setTimeout(() => controlador.abort(), TIMEOUT_RED_MS);
  try {
    return await fetch(url, { ...opciones, signal: controlador.signal });
  } finally {
    clearTimeout(id);
  }
}

// ---------------------------------------------------------------------------
// Entrada: parseo de CSV
// ---------------------------------------------------------------------------
function partirLineaCSV(linea) {
  const campos = [];
  let actual = '';
  let entreComillas = false;
  for (let i = 0; i < linea.length; i++) {
    const c = linea[i];
    if (c === '"') { entreComillas = !entreComillas; continue; }
    if (c === ',' && !entreComillas) { campos.push(actual.trim()); actual = ''; continue; }
    actual += c;
  }
  campos.push(actual.trim());
  return campos;
}

/**
 * Acepta el formato canónico [id,cliente,direccion,ventana_horaria,bultos,notas]
 * y el formato legado de la Entrega 1 [Cliente,Dirección] (con comas sin comillas
 * dentro de la dirección, por eso el corte en la primera coma).
 */
function parsearCSV(rutaArchivo) {
  const lineas = fs.readFileSync(rutaArchivo, 'utf-8')
    .split('\n').map(l => l.trim()).filter(l => l.length > 0);
  if (lineas.length === 0) throw new Error(`El archivo ${rutaArchivo} está vacío`);

  const encabezado = lineas[0].toLowerCase();
  const tieneEncabezado = encabezado.includes('cliente') || encabezado.includes('direcci');
  const canonico = encabezado.includes('ventana') || encabezado.includes('id,');

  const entregas = [];
  for (let i = tieneEncabezado ? 1 : 0; i < lineas.length; i++) {
    const partes = partirLineaCSV(lineas[i]);
    if (partes.length < 2) continue;

    let id, cliente, direccion, ventana, bultos, notas;
    if (canonico && partes.length >= 5 && /^ENT-/i.test(partes[0])) {
      [id, cliente, direccion, ventana, bultos, notas] = [partes[0], partes[1], partes[2], partes[3], partes[4], partes[5] || ''];
    } else if (canonico && partes.length >= 4) {
      [cliente, direccion, ventana, bultos, notas] = [partes[0], partes[1], partes[2], partes[3], partes[4] || ''];
      id = `ENT-${String(entregas.length + 1).padStart(2, '0')}`;
    } else {
      // Formato legado de 2 columnas: la dirección puede contener comas.
      const primeraComa = lineas[i].indexOf(',');
      cliente = lineas[i].slice(0, primeraComa).trim();
      direccion = lineas[i].slice(primeraComa + 1).trim().replace(/^"|"$/g, '');
      id = `ENT-${String(entregas.length + 1).padStart(2, '0')}`;
      ventana = ''; bultos = ''; notas = '';
    }

    const notasBajas = (notas || '').toLowerCase();
    entregas.push({
      id_entrega: id,
      cliente,
      direccion,
      ventana: parsearVentana(ventana),
      bultos: parseInt(bultos, 10) || 0,
      notas: notas || '',
      tiempo_atencion_min: /descarga pesada|30 ?min/.test(notasBajas) ? ATENCION_PESADA_MIN : ATENCION_ESTANDAR_MIN,
      carga_critica: /m[ée]dic|sensible|valores|refrigerad|controlad|urgente m/.test(notasBajas),
      acceso_dificil: /sin estacionamiento|dif[ií]cil acceso|zona de riesgo|peatonal|muelle/.test(notasBajas)
    });
  }
  return entregas;
}

// ---------------------------------------------------------------------------
// Herramienta 1: geocodificación (caché local → Nominatim → no resuelta)
// ---------------------------------------------------------------------------
function direccionAmbigua(direccion) {
  const d = direccion.toLowerCase();
  if (/\bs\/n\b|sin n[uú]mero|cerca de|frente a|altura\b/.test(d)) return true;
  return !/\d{2,}/.test(d); // sin altura catastral no hay punto único
}

/** Normaliza un nombre de calle: sin acentos, sin prefijos viales, sin puntuación. */
function normalizarCalle(texto) {
  return (texto || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/\b(av|avda|avenida|calle|cll|pasaje|psje|diag|diagonal|gral|general|dr|dra|pres|presidente)\b\.?/g, ' ')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Nombre de calle pedido: lo que aparece antes de la altura catastral. */
function calleSolicitada(direccion) {
  const m = /^(.*?)\s*\b\d{2,6}\b/.exec(direccion);
  return normalizarCalle(m ? m[1] : direccion);
}

/** ¿La calle devuelta por el proveedor es la que se pidió? */
function calleCoincide(pedida, devuelta) {
  const a = pedida, b = normalizarCalle(devuelta);
  if (!a || !b) return false;
  return a === b || a.includes(b) || b.includes(a);
}

/** Altura catastral pedida en la dirección (primer número de 2+ dígitos). */
function alturaSolicitada(direccion) {
  const m = /\b(\d{2,6})\b/.exec(direccion);
  return m ? m[1] : null;
}

/**
 * Caché de geocodificación con retención acotada: una entrada de más de CACHE_TTL_DIAS
 * se descarta al cargar. Sin esto, un dato de dirección quedaba guardado para siempre
 * y no había política de borrado que declarar en el apartado de gobierno.
 */
function cargarCache() {
  let bruta;
  try { bruta = JSON.parse(fs.readFileSync(CACHE_PATH, 'utf-8')); } catch (e) { return { datos: {}, purgadas: 0 }; }

  const limite = Date.now() - CACHE_TTL_DIAS * 24 * 60 * 60 * 1000;
  const datos = {};
  let purgadas = 0;
  for (const [clave, valor] of Object.entries(bruta)) {
    // Una entrada sin marca de tiempo es de un formato viejo: no se puede datar, se descarta.
    if (valor && typeof valor.ts === 'number' && valor.ts >= limite) datos[clave] = valor;
    else purgadas++;
  }
  return { datos, purgadas };
}

function guardarCache(cache) {
  fs.writeFileSync(CACHE_PATH, JSON.stringify(cache, null, 2), 'utf-8');
}

/** Token opaco e irrepetible para el enlace de seguimiento del cliente. */
function generarTokenSeguimiento() {
  return crypto.randomBytes(16).toString('base64url');
}

/**
 * Devuelve { lat, lng, fuente } o { error, motivo }.
 * Distingue "la dirección es ambigua" (culpa del dato) de "el geocodificador no
 * respondió" (culpa de la infraestructura): son dos incidentes distintos y el
 * despachador tiene que hacer cosas distintas con cada uno.
 */
async function geocodificar(direccion, cache, sinRed, contadores) {
  const clave = direccion.toLowerCase().trim();

  for (const [patron, coords] of Object.entries(COORDS_CONOCIDAS)) {
    if (clave.includes(patron)) { contadores.tabla_verificada++; return { ...coords, fuente: 'TABLA_VERIFICADA' }; }
  }
  if (cache[clave]) { contadores.cache_local++; return { ...cache[clave], fuente: 'CACHE_LOCAL' }; }

  if (direccionAmbigua(direccion)) {
    contadores.ambigua++;
    return { error: 'DIRECCION_AMBIGUA', motivo: 'La dirección no tiene altura catastral resoluble (s/n, "cerca de" o sin numeración). El agente no estima un punto aproximado.' };
  }
  if (sinRed) {
    contadores.geocoder_no_disponible++;
    return { error: 'GEOCODIFICACION_FALLIDA', motivo: 'Corrida en modo --sin-red: la dirección no está en la tabla verificada ni en la caché local.' };
  }

  const altura = alturaSolicitada(direccion);
  const calle = calleSolicitada(direccion);
  let ultimoMotivo = 'El geocodificador no devolvió resultados utilizables.';

  // Proveedor primario: Nominatim.
  for (let intento = 1; intento <= 3; intento++) {
    try {
      await esperar(PAUSA_NOMINATIM_MS * intento); // respeta el límite de 1 req/s y hace backoff ante 429
      const url = 'https://nominatim.openstreetmap.org/search?format=json&addressdetails=1&limit=1&countrycodes=ar&q=' +
                  encodeURIComponent(`${direccion}, Buenos Aires, Argentina`);
      const res = await fetchConTimeout(url, { headers: { 'User-Agent': USER_AGENT } });
      if (res.status === 429) { ultimoMotivo = 'Nominatim respondió 429 (límite de uso). Reintentos agotados.'; continue; }
      if (!res.ok) { ultimoMotivo = `Nominatim respondió HTTP ${res.status}.`; continue; }

      const datos = await res.json();
      if (datos.length === 0) { ultimoMotivo = 'Nominatim no encontró la dirección en Argentina.'; break; }

      const lat = parseFloat(datos[0].lat);
      const lng = parseFloat(datos[0].lon);
      // v0.2 inventaba coordenadas con jitter alrededor del depósito. Ahora, si
      // el punto cae fuera del AMBA, se declara no resuelto en vez de alucinarlo.
      if (!dentroDelAMBA(lat, lng)) {
        ultimoMotivo = `El punto devuelto (${lat.toFixed(4)}, ${lng.toFixed(4)}) cae fuera del bounding box del AMBA: geocodificación no confiable.`;
        break;
      }
      const dirNominatim = datos[0].address || {};
      if (altura && String(dirNominatim.house_number) !== altura) {
        ultimoMotivo = `Nominatim devolvió una coincidencia sin la altura ${altura} (devolvió ${dirNominatim.house_number || 'ninguna'}): es un punto de calle, no de portal.`;
        break;
      }
      if (calle && !calleCoincide(calle, dirNominatim.road)) {
        ultimoMotivo = `Nominatim devolvió la altura ${altura} pero sobre "${dirNominatim.road || 'calle desconocida'}", no sobre "${calle}".`;
        break;
      }
      cache[clave] = { lat, lng, ts: Date.now() };
      contadores.nominatim++;
      return { lat, lng, fuente: 'NOMINATIM' };
    } catch (e) {
      ultimoMotivo = `Fallo de red contra Nominatim (${e.name === 'AbortError' ? `timeout ${TIMEOUT_RED_MS} ms` : e.message}).`;
    }
  }

  // Proveedor de respaldo: Photon (OpenStreetMap, otro operador). Depender de un
  // único geocodificador convertía cualquier 429 ajeno en una entrega no despachable.
  for (let intento = 1; intento <= 2; intento++) {
    try {
      await esperar(500 * intento);
      const url = 'https://photon.komoot.io/api/?limit=1&q=' +
                  encodeURIComponent(`${direccion}, Buenos Aires, Argentina`);
      const res = await fetchConTimeout(url, { headers: { 'User-Agent': USER_AGENT } });
      if (!res.ok) { ultimoMotivo += ` Respaldo Photon: HTTP ${res.status}.`; continue; }

      const datos = await res.json();
      const rasgo = (datos.features || [])[0];
      if (!rasgo) { ultimoMotivo += ' Respaldo Photon: sin resultados.'; break; }

      const [lng, lat] = rasgo.geometry.coordinates;
      if (!dentroDelAMBA(lat, lng)) {
        ultimoMotivo += ` Respaldo Photon: punto (${lat.toFixed(4)}, ${lng.toFixed(4)}) fuera del AMBA.`;
        break;
      }
      // Sin esta comprobación, Photon devolvía un punto de "Avenida Corrientes" a la
      // altura 1300 para una dirección al 5400: 4 km de error, dentro del bounding box
      // y por lo tanto indetectable. Un match de calle no es un match de dirección.
      const propsPhoton = rasgo.properties || {};
      if (altura && String(propsPhoton.housenumber) !== altura) {
        ultimoMotivo += ` Respaldo Photon: coincidencia sin la altura ${altura} (devolvió ${propsPhoton.housenumber || 'ninguna'}); es un punto de calle, no de portal.`;
        break;
      }
      if (calle && !calleCoincide(calle, propsPhoton.street || propsPhoton.name)) {
        ultimoMotivo += ` Respaldo Photon: la altura ${altura} cae sobre "${propsPhoton.street || propsPhoton.name || 'calle desconocida'}", no sobre "${calle}".`;
        break;
      }
      cache[clave] = { lat, lng, ts: Date.now() };
      contadores.photon++;
      return { lat, lng, fuente: 'PHOTON' };
    } catch (e) {
      ultimoMotivo += ` Respaldo Photon: ${e.name === 'AbortError' ? `timeout ${TIMEOUT_RED_MS} ms` : e.message}.`;
    }
  }

  contadores.geocoder_no_disponible++;
  return { error: 'GEOCODIFICACION_FALLIDA', motivo: `${ultimoMotivo} Ambos geocodificadores (Nominatim y Photon) quedaron sin respuesta utilizable.` };
}

// ---------------------------------------------------------------------------
// Herramienta 2: matriz de tiempos/distancias viales (OSRM /table, 1 llamada)
// ---------------------------------------------------------------------------
async function construirMatriz(puntos, sinRed) {
  const n = puntos.length;
  const fallback = () => {
    const dur = [], dist = [];
    for (let i = 0; i < n; i++) {
      dur.push([]); dist.push([]);
      for (let j = 0; j < n; j++) {
        const km = distanciaHaversineKm(puntos[i].lat, puntos[i].lng, puntos[j].lat, puntos[j].lng);
        dist[i].push(km);
        dur[i].push(i === j ? 0 : Math.max(3, Math.round((km / VELOCIDAD_URBANA_KMH) * 60)));
      }
    }
    return { dur, dist, origen: `HAVERSINE_${VELOCIDAD_URBANA_KMH}KMH` };
  };

  if (sinRed || n < 2) return fallback();

  try {
    const coords = puntos.map(p => `${p.lng},${p.lat}`).join(';');
    const url = `http://router.project-osrm.org/table/v1/driving/${coords}?annotations=duration,distance`;
    const res = await fetchConTimeout(url, { headers: { 'User-Agent': USER_AGENT } });
    if (res.ok) {
      const datos = await res.json();
      if (datos.code === 'Ok' && datos.durations && datos.distances) {
        return {
          dur: datos.durations.map(fila => fila.map(s => Math.max(3, Math.round(s / 60)))),
          dist: datos.distances.map(fila => fila.map(m => m / 1000)),
          origen: 'OSRM_TABLE'
        };
      }
    }
  } catch (e) {
    // sin conectividad con OSRM: se degrada y se declara en meta_ejecucion
  }
  return fallback();
}

// ---------------------------------------------------------------------------
// Secuenciación: vecino más cercano + 2-opt, con factibilidad de ventana horaria
// ---------------------------------------------------------------------------

/**
 * Simula un orden completo de paradas y devuelve el cronograma resultante.
 * Es la única fuente de los tiempos: el resumen, el 2-opt y la autoverificación
 * leen todos de acá, así que no pueden discrepar entre sí.
 */
function evaluarOrden(orden, entregas, matriz, minutoInicio) {
  const pasos = [];
  let posicion = 0;
  let reloj = minutoInicio;
  let violaciones = 0;

  for (const idx of orden) {
    const viaje = matriz.dur[posicion][idx];
    const llegada = reloj + viaje;
    const ventana = entregas[idx - 1].ventana;
    const espera = ventana.inicio !== null ? Math.max(0, ventana.inicio - llegada) : 0;
    const inicioServicio = llegada + espera;
    const tarde = ventana.fin !== null && inicioServicio > ventana.fin;
    if (tarde) violaciones++;

    pasos.push({ idx, viaje, llegada, espera, inicioServicio, tarde });
    reloj = inicioServicio + entregas[idx - 1].tiempo_atencion_min;
    posicion = idx;
  }

  const viajeRegreso = matriz.dur[posicion][0];
  return {
    pasos,
    posicionFinal: posicion,
    relojFinal: reloj,
    total: reloj + viajeRegreso - minutoInicio,
    violaciones
  };
}

/** Construcción inicial: vecino más cercano penalizando la violación de ventanas. */
function construirGreedy(entregas, matriz, minutoInicio) {
  const pendientes = entregas.map((_, i) => i + 1); // 0 = depósito
  const orden = [];
  let posicion = 0;
  let reloj = minutoInicio;

  while (pendientes.length > 0) {
    let mejor = null;
    for (const idx of pendientes) {
      const viaje = matriz.dur[posicion][idx];
      const ventana = entregas[idx - 1].ventana;
      const espera = ventana.inicio !== null ? Math.max(0, ventana.inicio - (reloj + viaje)) : 0;
      const inicioServicio = reloj + viaje + espera;
      const tarde = ventana.fin !== null && inicioServicio > ventana.fin;
      const costo = viaje + espera + (tarde ? PENALIDAD_VENTANA_MIN : 0);
      const cierre = ventana.fin !== null ? ventana.fin : Infinity;
      if (!mejor || costo < mejor.costo || (costo === mejor.costo && cierre < mejor.cierre)) {
        mejor = { idx, costo, cierre, inicioServicio };
      }
    }
    pendientes.splice(pendientes.indexOf(mejor.idx), 1);
    orden.push(mejor.idx);
    reloj = mejor.inicioServicio + entregas[mejor.idx - 1].tiempo_atencion_min;
    posicion = mejor.idx;
  }
  return orden;
}

/**
 * Mejora 2-opt: invierte segmentos del recorrido y se queda con la inversión sólo si
 * reduce violaciones de ventana o, a igual cantidad, acorta la jornada.
 * El vecino más cercano solo bloqueaba jornadas (L3) que un orden mejor evitaba.
 */
function mejorarCon2opt(ordenInicial, entregas, matriz, minutoInicio) {
  let orden = ordenInicial.slice();
  let mejor = evaluarOrden(orden, entregas, matriz, minutoInicio);
  const inicial = mejor;
  let vueltas = 0;
  let huboMejora = true;

  while (huboMejora && vueltas < 60) {
    huboMejora = false;
    vueltas++;
    for (let i = 0; i < orden.length - 1 && !huboMejora; i++) {
      for (let j = i + 1; j < orden.length; j++) {
        const candidato = orden.slice(0, i)
          .concat(orden.slice(i, j + 1).reverse(), orden.slice(j + 1));
        const ev = evaluarOrden(candidato, entregas, matriz, minutoInicio);
        const mejora = ev.violaciones < mejor.violaciones ||
                       (ev.violaciones === mejor.violaciones && ev.total < mejor.total);
        if (mejora) {
          orden = candidato;
          mejor = ev;
          huboMejora = true;
          break;
        }
      }
    }
  }

  return {
    orden,
    evaluacion: mejor,
    diagnostico: {
      heuristico: 'vecino-mas-cercano + 2-opt',
      pasadas_2opt: vueltas,
      minutos_jornada_greedy: inicial.total,
      minutos_ahorrados_por_2opt: inicial.total - mejor.total,
      violaciones_ventana_greedy: inicial.violaciones,
      violaciones_ventana_final: mejor.violaciones
    }
  };
}

// ---------------------------------------------------------------------------
// Ejecución principal
// ---------------------------------------------------------------------------
async function ejecutar(opciones) {
  const iniciadoEn = new Date();
  const t0 = Date.now();

  if (!fs.existsSync(opciones.entrada)) {
    console.error(`❌ El archivo de entrada '${opciones.entrada}' no existe.`);
    process.exit(1);
  }
  const minutoInicio = hhmmAMinutos(opciones.inicio);
  if (minutoInicio === null) {
    console.error(`❌ --inicio inválido: '${opciones.inicio}'. Formato esperado HH:MM.`);
    process.exit(1);
  }

  console.log(`🤖 OptiRuta-Agent v${VERSION_AGENTE} — contrato: prompts/system_prompt.md`);
  console.log(`📄 Entrada: ${opciones.entrada} | Salida de depósito: ${opciones.inicio}${opciones.sinRed ? ' | modo --sin-red' : ''}`);

  const entregasCrudas = parsearCSV(opciones.entrada);
  const { datos: cache, purgadas: cachePurgadas } = cargarCache();
  if (cachePurgadas > 0) console.log(`🗑️  Caché: ${cachePurgadas} entrada/s vencida/s (> ${CACHE_TTL_DIAS} días) descartada/s.`);
  const contadores = { tabla_verificada: 0, cache_local: 0, nominatim: 0, photon: 0, ambigua: 0, geocoder_no_disponible: 0 };

  // --- Geocodificación ------------------------------------------------------
  const coordsDeposito = await geocodificar(opciones.deposito, cache, opciones.sinRed, contadores);
  if (coordsDeposito.error) {
    console.error(`❌ No se pudo geocodificar el depósito '${opciones.deposito}': ${coordsDeposito.motivo}`);
    console.error('   Sin origen confiable no hay plan que emitir.');
    process.exit(1);
  }

  const entregas = [];
  const noPlanificadas = [];
  for (const entrega of entregasCrudas) {
    const coords = await geocodificar(entrega.direccion, cache, opciones.sinRed, contadores);
    if (!coords.error) {
      entregas.push({ ...entrega, lat: coords.lat, lng: coords.lng, fuente_geocodificacion: coords.fuente });
    } else {
      noPlanificadas.push({
        id_entrega: entrega.id_entrega,
        cliente: entrega.cliente,
        direccion: entrega.direccion,
        tipo_incidente: coords.error,
        motivo: coords.motivo
      });
    }
  }
  guardarCache(cache);

  if (entregas.length === 0) {
    console.error('❌ Ninguna dirección pudo geocodificarse: no hay plan que emitir.');
    process.exit(1);
  }

  // --- Matriz vial y secuenciación -----------------------------------------
  const puntos = [{ lat: coordsDeposito.lat, lng: coordsDeposito.lng }, ...entregas];
  const matriz = await construirMatriz(puntos, opciones.sinRed);
  console.log(`🛰️  Matriz de tiempos: ${matriz.origen}`);

  const { orden, evaluacion, diagnostico } = mejorarCon2opt(
    construirGreedy(entregas, matriz, minutoInicio), entregas, matriz, minutoInicio);
  const ruta = evaluacion.pasos;
  const posicionFinal = evaluacion.posicionFinal;
  const relojFinal = evaluacion.relojFinal;
  if (diagnostico.minutos_ahorrados_por_2opt > 0) {
    console.log(`🔁 2-opt: ${diagnostico.minutos_ahorrados_por_2opt} min menos que el vecino más cercano (${diagnostico.minutos_jornada_greedy} → ${evaluacion.total} min)`);
  }

  // --- Armado de la salida --------------------------------------------------
  const secuencia = [];
  const alertas = [];
  const vencimientoTracking = new Date(iniciadoEn.getTime() + TRACKING_VIGENCIA_HS * 3600 * 1000).toISOString();
  let distanciaTotal = 0;
  let sumaViajes = 0, sumaEsperas = 0, sumaAtencion = 0;

  ruta.forEach((paso, i) => {
    const entrega = entregas[paso.idx - 1];
    const anterior = i === 0 ? 0 : ruta[i - 1].idx;
    const distTramo = matriz.dist[anterior][paso.idx];
    distanciaTotal += distTramo;
    sumaViajes += paso.viaje;
    sumaEsperas += paso.espera;
    sumaAtencion += entrega.tiempo_atencion_min;

    const alertasParada = [];
    if (paso.tarde) {
      alertasParada.push(`VENTANA_FUERA_DE_RANGO: llegada ${minutosAHhmm(paso.inicioServicio)} vs. cierre ${minutosAHhmm(entrega.ventana.fin)}.`);
      alertas.push({
        tipo: 'VENTANA_FUERA_DE_RANGO',
        descripcion: `${entrega.id_entrega} (${entrega.cliente}) llegaría ${paso.inicioServicio - entrega.ventana.fin} min después del cierre de su ventana ${entrega.ventana.texto}.`,
        accion_sugerida: 'El despachador reprograma la entrega o la reasigna a otra unidad antes de la salida (L2).'
      });
    }
    if (entrega.acceso_dificil) {
      alertasParada.push('ZONA_PELIGROSA: acceso restringido o sin estacionamiento.');
      alertas.push({
        tipo: 'ZONA_PELIGROSA',
        descripcion: `${entrega.id_entrega} (${entrega.direccion}): las notas indican acceso restringido o sin estacionamiento ("${entrega.notas}").`,
        accion_sugerida: 'El despachador confirma el protocolo de detención y descarga antes de iniciar la marcha (L2).'
      });
    }
    if (entrega.carga_critica) {
      alertasParada.push('CARGA_CRITICA: requiere firma del Jefe de Logística.');
      alertas.push({
        tipo: 'CARGA_CRITICA',
        descripcion: `${entrega.id_entrega} (${entrega.cliente}) transporta carga crítica o sensible según las notas ("${entrega.notas}").`,
        accion_sugerida: 'El Jefe de Logística firma la orden en el sistema antes de transmitirla al conductor (L4).'
      });
    }

    secuencia.push({
      orden: i + 1,
      id_entrega: entrega.id_entrega,
      cliente: entrega.cliente,
      direccion: entrega.direccion,
      lat: entrega.lat,
      lng: entrega.lng,
      fuente_geocodificacion: entrega.fuente_geocodificacion,
      ventana_horaria: entrega.ventana.texto,
      viaje_desde_anterior_min: paso.viaje,
      distancia_desde_anterior_km: parseFloat(distTramo.toFixed(2)),
      llegada_estimada: minutosAHhmm(paso.llegada),
      espera_min: paso.espera,
      eta_estimado: minutosAHhmm(paso.inicioServicio),
      tiempo_atencion_min: entrega.tiempo_atencion_min,
      salida_estimada: minutosAHhmm(paso.inicioServicio + entrega.tiempo_atencion_min),
      bultos: entrega.bultos,
      // Enlace de capacidad: token opaco de 128 bits con vencimiento. Antes era
      // `?stop=0&id=ENT-01`, enumerable: probando índices se veían las entregas de
      // otros clientes de la jornada. Ver DECISIONES.md §6.
      tracking_token: generarTokenSeguimiento(),
      tracking_expira: vencimientoTracking,
      alerta: alertasParada.length > 0 ? alertasParada.join(' | ') : null
    });
    secuencia[secuencia.length - 1].tracking_link =
      `${opciones.baseUrl}/cliente.html?t=${secuencia[secuencia.length - 1].tracking_token}`;
  });

  // Regreso al depósito: forma parte de la jornada del conductor.
  const viajeRegreso = matriz.dur[posicionFinal][0];
  const distanciaRegreso = matriz.dist[posicionFinal][0];
  distanciaTotal += distanciaRegreso;
  sumaViajes += viajeRegreso;
  const minutoFin = relojFinal + viajeRegreso;
  const tiempoTotal = minutoFin - minutoInicio;

  for (const np of noPlanificadas) {
    const esAmbigua = np.tipo_incidente === 'DIRECCION_AMBIGUA';
    alertas.push({
      tipo: np.tipo_incidente,
      descripcion: `${np.id_entrega} (${np.cliente}) quedó FUERA del plan. Dirección: "${np.direccion}". ${np.motivo}`,
      accion_sugerida: esAmbigua
        ? 'El despachador confirma la dirección exacta con el cliente y vuelve a correr el plan antes de la salida (L2).'
        : 'Incidente de infraestructura, no del dato: reintentar la corrida o cargar la coordenada a mano en la tabla verificada. La entrega NO puede despacharse hasta entonces (L2).'
    });
  }

  if (tiempoTotal > LIMITE_JORNADA_MIN) {
    alertas.push({
      tipo: 'EXCESO_JORNADA',
      descripcion: `La jornada proyectada es de ${tiempoTotal} min (${(tiempoTotal / 60).toFixed(2)} h), de ${minutosAHhmm(minutoInicio)} a ${minutosAHhmm(minutoFin)}, y supera el límite de ${LIMITE_JORNADA_MIN} min.`,
      accion_sugerida: 'Requiere aprobación L3 del despachador: autorizar horas extra o derivar las últimas paradas a una segunda unidad.'
    });
  }

  // --- Clasificación de supervisión (L0–L4) --------------------------------
  const tipos = new Set(alertas.map(a => a.tipo));
  let nivel;
  if (tipos.has('CARGA_CRITICA')) nivel = 'L4';
  else if (tipos.has('EXCESO_JORNADA')) nivel = 'L3';
  else if (tipos.has('DIRECCION_AMBIGUA') || tipos.has('GEOCODIFICACION_FALLIDA') ||
           tipos.has('VENTANA_FUERA_DE_RANGO') || tipos.has('ZONA_PELIGROSA')) nivel = 'L2';
  else if (tiempoTotal > UMBRAL_AUTONOMIA_MIN) nivel = 'L1';
  else nivel = 'L0';

  // --- Autoverificación aritmética -----------------------------------------
  // La falla de v1.0: el resumen decía 525 min mientras sus propios ETAs daban 375.
  // Ahora la suma de componentes tiene que cerrar contra el reloj o la corrida falla.
  const sumaComponentes = sumaViajes + sumaEsperas + sumaAtencion;
  const etasMonotonicos = secuencia.every((s, i) => i === 0 || s.eta_estimado >= secuencia[i - 1].salida_estimada);
  const tokens = secuencia.map(s => s.tracking_token);
  const tokensUnicos = new Set(tokens).size === tokens.length &&
                       tokens.every(t => typeof t === 'string' && t.length >= 20);
  const autoverificacion = {
    suma_componentes_min: sumaComponentes,
    coincide_con_reloj: sumaComponentes === tiempoTotal,
    etas_monotonicos: etasMonotonicos,
    entregas_en_csv: entregasCrudas.length,
    entregas_planificadas: secuencia.length,
    entregas_no_planificadas: noPlanificadas.length,
    cuadra_conteo_entregas: entregasCrudas.length === secuencia.length + noPlanificadas.length,
    tokens_seguimiento_unicos: tokensUnicos
  };

  const salida = {
    plan_id: `OPT-${iniciadoEn.toISOString().slice(0, 10).replace(/-/g, '')}-${String(secuencia.length).padStart(2, '0')}${nivel}`,
    fecha_ejecucion: iniciadoEn.toISOString(),
    deposito_origen: {
      direccion: opciones.deposito,
      lat: coordsDeposito.lat,
      lng: coordsDeposito.lng
    },
    resumen_jornada: {
      hora_inicio: minutosAHhmm(minutoInicio),
      hora_fin_estimada: minutosAHhmm(minutoFin),
      total_paradas: secuencia.length,
      tiempo_total_estimado_min: tiempoTotal,
      tiempo_viaje_min: sumaViajes,
      tiempo_espera_min: sumaEsperas,
      tiempo_atencion_min: sumaAtencion,
      distancia_total_km: parseFloat(distanciaTotal.toFixed(2)),
      cumple_limite_8hs: tiempoTotal <= LIMITE_JORNADA_MIN,
      nivel_supervision_requerido: nivel
    },
    secuencia_recorrido: secuencia,
    entregas_no_planificadas: noPlanificadas,
    alertas_y_riesgos: alertas,
    meta_ejecucion: {
      version_agente: VERSION_AGENTE,
      motor: 'agente.js (planificador determinista, sin LLM)',
      comando: `node ${path.basename(__filename)} ${process.argv.slice(2).join(' ')}`,
      duracion_ejecucion_ms: Date.now() - t0,
      fuente_matriz_tiempos: matriz.origen,
      fuentes_geocodificacion: contadores,
      optimizacion: diagnostico,
      retencion: {
        cache_geocodificacion_dias: CACHE_TTL_DIAS,
        cache_entradas_purgadas: cachePurgadas,
        tracking_vigencia_horas: TRACKING_VIGENCIA_HS,
        tracking_expira: vencimientoTracking
      },
      autoverificacion
    }
  };

  // --- Validación contra el contrato ---------------------------------------
  const { valido, errores } = validarContraContrato(salida);
  salida.meta_ejecucion.contrato_validado = valido;

  fs.writeFileSync(opciones.salida, JSON.stringify(salida, null, 2), 'utf-8');

  console.log(`📊 ${secuencia.length} paradas | ${tiempoTotal} min (${(tiempoTotal / 60).toFixed(2)} h) | ${distanciaTotal.toFixed(1)} km | ${minutosAHhmm(minutoInicio)}→${minutosAHhmm(minutoFin)}`);
  console.log(`🛡️  Nivel de supervisión: ${nivel}${alertas.length ? ` (${alertas.length} alerta/s: ${[...tipos].join(', ')})` : ''}`);
  console.log(`🧮 Autoverificación: suma ${sumaComponentes} min vs. reloj ${tiempoTotal} min → ${autoverificacion.coincide_con_reloj ? 'OK' : 'INCONSISTENTE'}`);
  console.log(`📐 Geocodificación: ${JSON.stringify(contadores)}`);
  console.log(`💾 Salida: ${path.resolve(opciones.salida)}`);

  const fallas = [];
  if (!valido) fallas.push(...errores.map(e => `contrato: ${e}`));
  if (!autoverificacion.coincide_con_reloj) fallas.push('aritmética: la suma de componentes no coincide con el reloj');
  if (!autoverificacion.etas_monotonicos) fallas.push('aritmética: los ETAs no son monótonos');
  if (!autoverificacion.cuadra_conteo_entregas) fallas.push('trazabilidad: no cuadra el conteo de entregas del CSV');
  if (!autoverificacion.tokens_seguimiento_unicos) fallas.push('seguridad: los tokens de seguimiento no son únicos o son demasiado cortos');

  if (fallas.length > 0) {
    console.error('❌ La corrida NO pasó las verificaciones (la salida igual se guardó como evidencia):');
    fallas.forEach(f => console.error(`   - ${f}`));
    process.exit(1);
  }
  console.log('✅ Corrida válida: cumple el contrato y la autoverificación aritmética.');
}

ejecutar(parsearArgs(process.argv.slice(2))).catch(e => {
  console.error(`❌ Error no controlado: ${e.message}`);
  process.exit(1);
});

