  function updateDepotMarker(lat, lng, address) {
    markersLayerGroup.clearLayers();
    routeLayerGroup.clearLayers();

    const depotIcon = L.divIcon({
      className: 'custom-pin-wrapper',
      html: `<div class="custom-pin depot-pin" title="Origen: ${address}">🏠</div>`,
      iconSize: [32, 32],
      iconAnchor: [16, 16]
    });

    L.marker([lat, lng], { icon: depotIcon })
      .bindPopup(`<b>🏠 Origen / Depósito</b><br>${address}`)
      .addTo(markersLayerGroup);

    map.setView([lat, lng], 13);
  }

  // Token opaco de 128 bits para el enlace del cliente (mismo criterio que agente.js).
  function generarTokenSeguimiento() {
    const bytes = new Uint8Array(16);
    crypto.getRandomValues(bytes);
    return btoa(String.fromCharCode(...bytes)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  }

  const VIGENCIA_TRACKING_MS = 24 * 60 * 60 * 1000;

  // --------------------------------------------------------------------------
  // Geocodificación
  // --------------------------------------------------------------------------
  async function geocodeAddress(rawText, index = 0, baseCoords = DEFAULT_DEPOT) {
    const cleanText = rawText.trim();
    if (!cleanText) return null;

    let name = `Cliente #${index + 1}`;
    let address = cleanText;

    if (cleanText.includes(',')) {
      const parts = cleanText.split(',');
      if (parts.length >= 2 && !parts[0].toLowerCase().includes('av') && !parts[0].toLowerCase().includes('calle')) {
        name = parts[0].trim();
        address = parts.slice(1).join(',').trim();
      }
    }

    for (const key in KNOWN_COORDS) {
      if (address.toLowerCase().includes(key.toLowerCase()) || cleanText.toLowerCase().includes(key.toLowerCase())) {
        return {
          id: index,
          name: name,
          address: address,
          lat: KNOWN_COORDS[key].lat,
          lng: KNOWN_COORDS[key].lng
        };
      }
    }

    // Sin altura catastral no se sale a la red: no hay punto único que buscar.
    const dLower = address.toLowerCase();
    const esAmbigua = /\bs\/n\b|sin n[uú]mero|sin numero|cerca de|frente a/.test(dLower) || !/\d{2,}/.test(dLower);
    if (esAmbigua) return null;

    const query = encodeURIComponent(`${address}, Buenos Aires, Argentina`);
    const dentroAMBA = (lat, lng) => lat >= -34.90 && lat <= -34.40 && lng >= -58.80 && lng <= -58.20;
    // Altura pedida: si el proveedor no la confirma, es un punto de calle y no sirve.
    const alturaMatch = /\b(\d{2,6})\b/.exec(address);
    const altura = alturaMatch ? alturaMatch[1] : null;

    const fetchConTimeout = async (url) => {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 6000);
      try { return await fetch(url, { signal: controller.signal }); }
      finally { clearTimeout(timeoutId); }
    };

    // Proveedor primario: Nominatim.
    try {
      const res = await fetchConTimeout(`https://nominatim.openstreetmap.org/search?format=json&addressdetails=1&countrycodes=ar&limit=1&q=${query}`);
      if (res.ok) {
        const data = await res.json();
        if (data && data.length > 0) {
          const lat = parseFloat(data[0].lat), lng = parseFloat(data[0].lon);
          const hn = data[0].address && data[0].address.house_number;
          if (dentroAMBA(lat, lng) && (!altura || String(hn) === altura)) {
            return { id: index, name, address, lat, lng };
          }
        }
      }
    } catch (e) {
      // Nominatim no manda cabeceras CORS en sus respuestas de error (429), así que
      // desde el navegador un límite de tasa llega como "Failed to fetch". Por eso
      // hay un segundo proveedor: sin él, la app web sólo resolvía la tabla local.
    }

    // Proveedor de respaldo: Photon (sirve CORS).
    try {
      const res = await fetchConTimeout(`https://photon.komoot.io/api/?limit=1&q=${query}`);
      if (res.ok) {
        const data = await res.json();
        const f = (data.features || [])[0];
        if (f) {
          const [lng, lat] = f.geometry.coordinates;
          const hn = f.properties && f.properties.housenumber;
          if (dentroAMBA(lat, lng) && (!altura || String(hn) === altura)) {
            return { id: index, name, address, lat, lng };
          }
        }
      }
    } catch (e) {}

    // Si no hay coordenada confiable, se devuelve null y la entrega queda SIN planificar.
    // v1.0 inventaba un punto con jitter alrededor del depósito: eso es exactamente la
    // "alucinación espacial" que el contrato prohíbe (system_prompt.md §5).
    return null;
  }

  // --------------------------------------------------------------------------
  // Optimización de Ruta
  // --------------------------------------------------------------------------
  function calculateDistanceKm(lat1, lon1, lat2, lon2) {
    const R = 6371;
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
              Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * 
              Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
  }

  function optimizeStopsOrder(depot, stops) {
    if (stops.length <= 1) return stops;

    let unvisited = [...stops];
    let route = [];
    let currentPoint = depot;

    while (unvisited.length > 0) {
      let nearestIdx = 0;
      let minDistance = Infinity;

      for (let i = 0; i < unvisited.length; i++) {
        const dist = calculateDistanceKm(currentPoint.lat, currentPoint.lng, unvisited[i].lat, unvisited[i].lng);
        if (dist < minDistance) {
          minDistance = dist;
          nearestIdx = i;
        }
      }

      const nextStop = unvisited.splice(nearestIdx, 1)[0];
      route.push(nextStop);
      currentPoint = nextStop;
    }

    return route;
  }

  function calculateShiftTimes(depot, orderedStops, startTimeStr, shiftHours, serviceMinutes) {
    const maxShiftMinutes = shiftHours * 60;
    const [startH, startM] = startTimeStr.split(':').map(Number);
    let currentMinutesFromMidnight = (startH * 60) + startM;
    let accumulatedShiftMinutes = 0;

    let previousPoint = depot;

    return orderedStops.map((stop, index) => {
      const dist = calculateDistanceKm(previousPoint.lat, previousPoint.lng, stop.lat, stop.lng);
      const travelMinutes = Math.max(3, Math.round((dist / 25) * 60));

      const arrivalMinutes = currentMinutesFromMidnight + travelMinutes;
      const departureMinutes = arrivalMinutes + serviceMinutes;

      accumulatedShiftMinutes += travelMinutes + serviceMinutes;
      const isWithinShift = accumulatedShiftMinutes <= maxShiftMinutes;

      previousPoint = stop;
      currentMinutesFromMidnight = departureMinutes;

      return {
        ...stop,
        stepNumber: index + 1,
        deliveryId: stop.deliveryId || `ENT-${String(index + 1).padStart(2, '0')}`,
        distanceFromPrev: dist.toFixed(1),
        travelMinutes: travelMinutes,
        arrivalTime: formatTime(arrivalMinutes),
        departureTime: formatTime(departureMinutes),
        accumulatedMinutes: accumulatedShiftMinutes,
        isWithinShift: isWithinShift,
        status: 'PENDING' // PENDING, EN_CAMINO, DELIVERED
      };
    });
  }

  function formatTime(totalMinutes) {
    const mins = totalMinutes % (24 * 60);
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
  }

  // --------------------------------------------------------------------------
  // Trazado de Ruta e Interpolación para Simulación
  // --------------------------------------------------------------------------
  async function drawRouteOnMap(depot, stops) {
    routeLayerGroup.clearLayers();
    routePathPoints = [];
    if (stops.length === 0) return;

    const points = [depot, ...stops];
    const coordsStr = points.map(p => `${p.lng},${p.lat}`).join(';');

    let polylineDrawn = false;

    try {
      const res = await fetch(`https://router.project-osrm.org/route/v1/driving/${coordsStr}?overview=full&geometries=geojson`);
      if (res.ok) {
        const data = await res.json();
        if (data.routes && data.routes.length > 0) {
          const routeGeometry = data.routes[0].geometry;

          L.geoJSON(routeGeometry, {
            style: { color: '#3b82f6', weight: 5, opacity: 0.8, dashArray: '8, 8' }
          }).addTo(routeLayerGroup);

          // Extraer puntos lat/lng para la animación
          const coords = routeGeometry.coordinates;
          coords.forEach(c => {
            routePathPoints.push({ lat: c[1], lng: c[0] });
          });

          polylineDrawn = true;
        }
      }
    } catch (e) {}

    if (!polylineDrawn) {
      const latLngs = points.map(p => [p.lat, p.lng]);
      L.polyline(latLngs, { color: '#10b981', weight: 4, opacity: 0.8 }).addTo(routeLayerGroup);

      // Interpolar puntos simples entre paradas
      for (let i = 0; i < points.length - 1; i++) {
        const p1 = points[i];
        const p2 = points[i + 1];
        const steps = 30;
        for (let s = 0; s <= steps; s++) {
          routePathPoints.push({
            lat: p1.lat + (p2.lat - p1.lat) * (s / steps),
            lng: p1.lng + (p2.lng - p1.lng) * (s / steps)
          });
        }
      }
    }

    // Interpolar puntos adicionales para movimiento ultra-fluido
    routePathPoints = denseInterpolatePoints(routePathPoints);

    // Guardar estado completo en localStorage para la vista cliente
    syncStateToStorage();
  }

  function denseInterpolatePoints(points) {
    if (points.length <= 1) return points;
    const dense = [];
    for (let i = 0; i < points.length - 1; i++) {
      const p1 = points[i];
      const p2 = points[i + 1];
      const subSteps = 5;
      for (let k = 0; k < subSteps; k++) {
        dense.push({
          lat: p1.lat + (p2.lat - p1.lat) * (k / subSteps),
          lng: p1.lng + (p2.lng - p1.lng) * (k / subSteps)
        });
      }
    }
    dense.push(points[points.length - 1]);
    return dense;
  }

  // --------------------------------------------------------------------------
  // Simulación del Repartidor en Tiempo Real
  // --------------------------------------------------------------------------
  function toggleLiveSimulation() {
    const btn = document.getElementById('btn-toggle-live');
    if (isSimulating) {
      pauseLiveSimulation();
      btn.textContent = '▶ Continuar Recorrido';
      btn.className = 'btn btn-success btn-sm';
    } else {
      startLiveSimulation();
      btn.textContent = '⏸ Pausar Recorrido';
      btn.className = 'btn btn-secondary btn-sm';
    }
  }

  function startLiveSimulation() {
    if (routePathPoints.length === 0) return;
    isSimulating = true;

    const speed = parseInt(document.getElementById('sim-speed').value) || 5;
    const intervalMs = Math.max(40, 300 / speed);

    if (!driverMarker) {
      const driverIcon = L.divIcon({
        className: 'custom-pin-wrapper',
        html: `<div class="custom-pin driver-pin" title="Repartidor Live">🚚</div>`,
        iconSize: [36, 36],
        iconAnchor: [18, 18]
      });
      driverMarker = L.marker([routePathPoints[0].lat, routePathPoints[0].lng], { icon: driverIcon }).addTo(map);
    }

    clearInterval(simIntervalId);
    simIntervalId = setInterval(() => {
      if (simCurrentPointIndex >= routePathPoints.length) {
        pauseLiveSimulation();
        document.getElementById('btn-toggle-live').textContent = '✅ Recorrido Completado';
        return;
      }

      const currentPos = routePathPoints[simCurrentPointIndex];
      driverMarker.setLatLng([currentPos.lat, currentPos.lng]);

      // Encontrar la parada más cercana para actualizar estados
      updateCurrentTargetStop(currentPos);

      // Transmitir posición live
      broadcastLivePosition(currentPos);

      simCurrentPointIndex++;
    }, intervalMs);
  }

  function pauseLiveSimulation() {
    isSimulating = false;
    clearInterval(simIntervalId);
  }

  function resetLiveSimulation() {
    pauseLiveSimulation();
    simCurrentPointIndex = 0;
    if (driverMarker && routePathPoints.length > 0) {
      driverMarker.setLatLng([routePathPoints[0].lat, routePathPoints[0].lng]);
    }
    currentStops.forEach(s => s.status = 'PENDING');
    renderResults(currentDepot, currentStops);
    document.getElementById('btn-toggle-live').textContent = '▶ Iniciar Recorrido';
    document.getElementById('btn-toggle-live').className = 'btn btn-success btn-sm';
  }

  function updateCurrentTargetStop(driverPos) {
    if (currentStops.length === 0) return;

    for (let i = 0; i < currentStops.length; i++) {
      const stop = currentStops[i];
      const dist = calculateDistanceKm(driverPos.lat, driverPos.lng, stop.lat, stop.lng);

      if (dist < 0.25) { // Si el repartidor está a menos de 250 metros
        stop.status = 'DELIVERED';
      } else if (dist < 1.5 && stop.status === 'PENDING') {
        stop.status = 'EN_CAMINO';
      }
    }

    syncStateToStorage(driverPos);
  }

  function broadcastLivePosition(driverPos) {
    const liveData = {
      driverPos: driverPos,
      simIndex: simCurrentPointIndex,
      stops: currentStops,
      depot: currentDepot,
      timestamp: Date.now()
    };

    localStorage.setItem('optiruta_live_data', JSON.stringify(liveData));

    if (broadcastChannel) {
      broadcastChannel.postMessage(liveData);
    }
  }

  function syncStateToStorage(driverPos = null) {
    const fullState = {
      depot: currentDepot,
      stops: currentStops,
      routePathPoints: routePathPoints,
      driverPos: driverPos || (routePathPoints.length > 0 ? routePathPoints[0] : currentDepot),
      updatedAt: Date.now()
    };
    localStorage.setItem('optiruta_full_route', JSON.stringify(fullState));
  }

  // --------------------------------------------------------------------------
  // Generación de Links para Clientes
  // --------------------------------------------------------------------------
  window.copyClientLink = function(stopIndex) {
    syncStateToStorage();

    const baseUrl = window.location.href.substring(0, window.location.href.lastIndexOf('/'));
    const stop = currentStops[stopIndex];
    if (!stop || !stop.trackingToken) {
      alert('⚠️ Esta parada no tiene token de seguimiento. Volvé a optimizar o recargá el output.json del agente.');
      return;
    }
    const clientUrl = `${baseUrl}/cliente.html?t=${stop.trackingToken}`;

    navigator.clipboard.writeText(clientUrl).then(() => {
      alert(`✅ Link copiado para el cliente #${stopIndex + 1}:\n\n${clientUrl}\n\n¡Puedes enviárselo por WhatsApp o email para ver su entrega en vivo!`);
    }).catch(() => {
      prompt(`Copia este link para el cliente #${stopIndex + 1}:`, clientUrl);
    });
  };

  // --------------------------------------------------------------------------
  // Renderizado de Marcadores y Tarjetas
  // --------------------------------------------------------------------------
  function renderResults(depot, stops) {
    markersLayerGroup.clearLayers();

    const depotIcon = L.divIcon({
      className: 'custom-pin-wrapper',
      html: `<div class="custom-pin depot-pin">🏠</div>`,
      iconSize: [36, 36],
      iconAnchor: [18, 18]
    });
    L.marker([depot.lat, depot.lng], { icon: depotIcon })
      .bindPopup(`<b>🏠 Origen / Depósito</b><br>${depot.address}`)
      .addTo(markersLayerGroup);

    const bounds = L.latLngBounds([[depot.lat, depot.lng]]);

    stops.forEach((stop, index) => {
      bounds.extend([stop.lat, stop.lng]);

      const statusClass = stop.isWithinShift ? 'on-time-pin' : 'exceeded-pin';
      const iconHtml = `<div class="custom-pin ${statusClass}" id="pin-stop-${index}">${stop.stepNumber}</div>`;

      const customIcon = L.divIcon({
        className: 'custom-pin-wrapper',
        html: iconHtml,
        iconSize: [32, 32],
        iconAnchor: [16, 16]
      });

      const marker = L.marker([stop.lat, stop.lng], { icon: customIcon }).addTo(markersLayerGroup);

      const statusBadge = stop.isWithinShift 
        ? '<span style="color:#10b981; font-weight:bold;">🟢 En Turno (≤8h)</span>'
        : '<span style="color:#f59e0b; font-weight:bold;">🟠 Excede 8h</span>';

      marker.bindPopup(`
        <div style="font-family: sans-serif; font-size: 13px;">
          <h4 style="margin: 0 0 6px 0;">Entrega #${stop.stepNumber}: ${stop.name}</h4>
          <p style="margin: 0 0 4px 0; color: #64748b;">${stop.address}</p>
          <hr style="border: 0; border-top: 1px solid #e2e8f0; margin: 8px 0;">
          <p style="margin: 2px 0;">⏰ <b>Llegada est.:</b> ${stop.arrivalTime}</p>
          <p style="margin: 2px 0;">🚪 <b>Salida est.:</b> ${stop.departureTime}</p>
          <p style="margin: 2px 0;">🚗 <b>Tránsito:</b> ${stop.travelMinutes} min (${stop.distanceFromPrev} km)</p>
          <p style="margin: 6px 0 0 0;">${statusBadge}</p>
          <button onclick="copyClientLink(${index})" style="margin-top:8px; width:100%; padding:6px; background:#3b82f6; color:white; border:none; border-radius:4px; cursor:pointer; font-weight:bold;">🔗 Copiar Link Cliente</button>
        </div>
      `);

      marker.on('click', () => highlightStop(index));
    });

    map.fitBounds(bounds, { padding: [50, 50] });

    const onTimeContainer = document.getElementById('on-time-stops-list');
    const exceededContainer = document.getElementById('exceeded-stops-list');
    const exceededTitle = document.getElementById('exceeded-section-title');

    onTimeContainer.innerHTML = '';
    exceededContainer.innerHTML = '';

    const onTimeStops = stops.filter(s => s.isWithinShift);
    const exceededStops = stops.filter(s => !s.isWithinShift);

    document.getElementById('stat-on-time').textContent = onTimeStops.length;
    document.getElementById('stat-exceeded').textContent = exceededStops.length;

    const lastStop = stops[stops.length - 1];
    if (lastStop) {
      const totalHours = (lastStop.accumulatedMinutes / 60).toFixed(1);
      document.getElementById('stat-total-time').textContent = `${totalHours}h`;
    }

    let totalDist = stops.reduce((acc, s) => acc + parseFloat(s.distanceFromPrev), 0);
    document.getElementById('stat-total-dist').textContent = `${totalDist.toFixed(1)} km`;

    onTimeStops.forEach(stop => onTimeContainer.appendChild(createStopCardHTML(stop)));

    if (exceededStops.length > 0) {
      exceededTitle.style.display = 'block';
      exceededStops.forEach(stop => exceededContainer.appendChild(createStopCardHTML(stop)));
    } else {
      exceededTitle.style.display = 'none';
    }

    document.getElementById('results-count-badge').textContent = `${stops.length} entregas totales`;
    document.getElementById('results-section').style.display = 'block';

    renderAgentGovernance(depot, stops, parseFloat(document.getElementById('shift-hours').value) || 8);

    if (stops.length > 0) {
      highlightStop(0);
    }
  }

  // --------------------------------------------------------------------------
  // Lógica Agéntica y Gobierno L0-L4
  // --------------------------------------------------------------------------
  let lastAgentOutputJson = null;

  function renderAgentGovernance(depot, stops, shiftHours) {
    const governanceSection = document.getElementById('agent-governance-section');
    const badgeEl = document.getElementById('supervision-badge');
    const contractStatusEl = document.getElementById('agent-contract-status');
    const supervisionDescEl = document.getElementById('agent-supervision-desc');
    const alertsWrapper = document.getElementById('agent-alerts-wrapper');
    const alertsListEl = document.getElementById('agent-alerts-list');

    if (!governanceSection) return;

    const exceededStops = stops.filter(s => !s.isWithinShift);
    const ambiguousStops = stops.filter(s => 
      s.address.toLowerCase().includes('s/n') || 
      s.address.toLowerCase().includes('sin número') || 
      s.address.toLowerCase().includes('cerca')
    );

    let level = 'L0';
    let levelDesc = 'L0 (Autónomo - Ejecución directa sin intervención)';
    let contractStatus = '🟢 Cumple Límite 8h';
    let contractClass = 'status-ok';
    const alerts = [];

    if (ambiguousStops.length > 0) {
      level = 'L2';
      levelDesc = 'L2 (Supervisión por Excepción - Dirección Ambigua)';
      ambiguousStops.forEach(s => {
        alerts.push({
          tipo: 'DIRECCION_AMBIGUA',
          descripcion: `La dirección '${s.address}' requiere validación catastral previa.`,
          accion_sugerida: 'Confirmar altura exacta o coordenadas con el cliente antes del despacho.'
        });
      });
    }

    if (exceededStops.length > 0) {
      level = 'L3';
      levelDesc = `L3 (Aprobación Previa - ${exceededStops.length} paradas exceden el turno de ${shiftHours}h)`;
      contractStatus = `🔴 Exceso de Jornada (${exceededStops.length} excedidas)`;
      contractClass = 'status-warning';
      alerts.push({
        tipo: 'EXCESO_JORNADA',
        descripcion: `El recorrido proyectado supera el límite configurado de ${shiftHours} horas.`,
        accion_sugerida: 'Requiere autorización L3 del despachador para horas extras o reasignación a un vehículo secundario.'
      });
    }

    // Actualizar badges e info de gobernanza en la interfaz
    badgeEl.textContent = `${level} - ${level === 'L0' ? 'Autónomo' : level === 'L2' ? 'Excepción' : 'Aprobación Previa'}`;
    badgeEl.className = `supervision-tag ${level.toLowerCase()}`;
    contractStatusEl.textContent = contractStatus;
    contractStatusEl.className = contractClass;
    supervisionDescEl.textContent = levelDesc;

    if (alerts.length > 0) {
      alertsWrapper.style.display = 'block';
      alertsListEl.innerHTML = alerts.map(a => `
        <div class="agent-alert-item">
          <strong>⚠️ ${a.tipo}:</strong> ${a.descripcion}
          <div style="font-size:10px; color:#94a3b8; margin-top:2px;">💡 <b>Acción sugerida:</b> ${a.accion_sugerida}</div>
        </div>
      `).join('');
    } else {
      alertsWrapper.style.display = 'none';
      alertsListEl.innerHTML = '';
    }

    governanceSection.style.display = 'block';

    // Generar JSON estructurado formal conforme al System Prompt
    const baseUrl = window.location.href.substring(0, window.location.href.lastIndexOf('/'));
    lastAgentOutputJson = {
      plan_id: `OPT-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${Math.floor(100 + Math.random()*900)}`,
      fecha_ejecucion: new Date().toISOString(),
      deposito_origen: depot,
      resumen_jornada: {
        total_paradas: stops.length,
        tiempo_total_estimado_min: stops.length > 0 ? stops[stops.length - 1].accumulatedMinutes : 0,
        distancia_total_km: parseFloat(stops.reduce((acc, s) => acc + parseFloat(s.distanceFromPrev), 0).toFixed(1)),
        cumple_limite_8hs: exceededStops.length === 0,
        nivel_supervision_requerido: level
      },
      secuencia_recorrido: stops.map((s, idx) => ({
        orden: idx + 1,
        id_entrega: s.deliveryId || `ENT-${String(idx + 1).padStart(2, '0')}`,
        cliente: s.name,
        direccion: s.address,
        lat: s.lat,
        lng: s.lng,
        eta_estimado: s.arrivalTime,
        tiempo_atencion_min: 15,
        tracking_token: s.trackingToken || null,
        tracking_expira: s.trackingExpira || null,
        tracking_link: s.trackingToken ? `${baseUrl}/cliente.html?t=${s.trackingToken}` : null,
        alerta: !s.isWithinShift ? 'EXCESO_JORNADA' : null
      })),
      alertas_y_riesgos: alerts
    };
  }

  function createStopCardHTML(stop) {
    const card = document.createElement('div');
    const stopIdx = stop.stepNumber - 1;
    card.className = `stop-card ${stop.isWithinShift ? '' : 'exceeded'} ${stop.status === 'DELIVERED' ? 'completed' : ''}`;
    card.id = `stop-card-${stopIdx}`;

    card.innerHTML = `
      <div class="stop-badge">${stop.stepNumber}</div>
      <div class="stop-details">
        <div class="stop-title">${stop.name}</div>
        <div class="stop-sub">${stop.address}</div>
        <div class="stop-actions">
          <button class="btn btn-share" onclick="event.stopPropagation(); copyClientLink(${stopIdx})">🔗 Link Cliente</button>
        </div>
      </div>
      <div class="stop-time">
        <div class="arrival">${stop.arrivalTime}</div>
        <div class="duration">${stop.travelMinutes}m viaje</div>
      </div>
    `;

    card.addEventListener('click', () => highlightStop(stopIdx));
    return card;
  }

  function highlightStop(index) {
    if (index < 0 || index >= currentStops.length) return;

    activeStopIndex = index;
    const stop = currentStops[index];

    document.querySelectorAll('.stop-card').forEach(c => c.classList.remove('active'));
    document.querySelectorAll('.custom-pin').forEach(p => p.classList.remove('active-pin'));

    const activeCard = document.getElementById(`stop-card-${index}`);
    if (activeCard) {
      activeCard.classList.add('active');
      activeCard.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }

    const activePin = document.getElementById(`pin-stop-${index}`);
    if (activePin) {
      activePin.classList.add('active-pin');
    }

    // Leaflet devuelve LatLng(NaN, NaN) al animar sobre un contenedor de 0x0
    // (viewport angosto, panel colapsado) y rompe todo el flujo. Guardas explícitas.
    const size = map.getSize();
    if (Number.isFinite(stop.lat) && Number.isFinite(stop.lng) && size.x > 0 && size.y > 0) {
      map.flyTo([stop.lat, stop.lng], 15, { duration: 0.8 });
    } else if (Number.isFinite(stop.lat) && Number.isFinite(stop.lng)) {
      map.setView([stop.lat, stop.lng], 15, { animate: false });
    }
    document.getElementById('tour-current-name').textContent = `#${stop.stepNumber} - ${stop.name}`;
  }

  // --------------------------------------------------------------------------
  // Procesamiento de Optimización
  // --------------------------------------------------------------------------
  async function processOptimization() {
    const depotAddressInput = document.getElementById('depot-address').value.trim();
    const addressText = document.getElementById('address-text').value.trim();
    const startTimeStr = document.getElementById('start-time').value;
    const shiftHours = parseFloat(document.getElementById('shift-hours').value) || 8;
    const serviceMinutes = parseInt(document.getElementById('service-time').value) || 15;

    if (!addressText) {
      alert('Por favor, ingresa o carga un documento con direcciones de entrega.');
      return;
    }

    const overlay = document.getElementById('loading-overlay');
    const loadingText = document.getElementById('loading-text');
    overlay.style.display = 'flex';

    loadingText.textContent = 'OptiRuta-Agent geocodificando depósito...';
    const depotRes = await geocodeAddress(depotAddressInput || DEFAULT_DEPOT.address, 0);
    currentDepot = depotRes || DEFAULT_DEPOT;

    const lines = addressText.split('\n').map(l => l.trim()).filter(l => l.length > 0);
    loadingText.textContent = `OptiRuta-Agent validando ${lines.length} clientes...`;

    const geocodedStops = [];
    const unresolvedStops = [];
    for (let i = 0; i < lines.length; i++) {
      const stopData = await geocodeAddress(lines[i], i, currentDepot);
      if (stopData) {
        stopData.deliveryId = `ENT-${String(geocodedStops.length + 1).padStart(2, '0')}`;
        stopData.trackingToken = generarTokenSeguimiento();
        stopData.trackingExpira = new Date(Date.now() + VIGENCIA_TRACKING_MS).toISOString();
        geocodedStops.push(stopData);
      } else {
        unresolvedStops.push(lines[i]);
      }
    }

    if (geocodedStops.length === 0) {
      overlay.style.display = 'none';
      alert('⚠️ Ninguna dirección pudo geocodificarse con confianza. No se emite plan.');
      return;
    }

    try {
      loadingText.textContent = 'OptiRuta-Agent calculando orden geográfico óptimo...';
      const orderedStops = optimizeStopsOrder(currentDepot, geocodedStops);

      loadingText.textContent = 'Evaluando contrato de 8 horas y supervisión L0-L4...';
      currentStops = calculateShiftTimes(currentDepot, orderedStops, startTimeStr, shiftHours, serviceMinutes);

      loadingText.textContent = 'Trazando ruta y generando tokens de tracking...';
      await drawRouteOnMap(currentDepot, currentStops);

      renderResults(currentDepot, currentStops);
    } catch (e) {
      console.error('OptiRuta-Agent: fallo al renderizar el plan', e);
      alert('⚠️ El plan se calculó pero falló al dibujarse: ' + e.message);
    } finally {
      // El overlay se cierra siempre: una excepción al dibujar dejaba la app colgada.
      overlay.style.display = 'none';
    }

    if (unresolvedStops.length > 0) {
      // Supervisión L2: el agente no adivina la dirección, la devuelve al humano.
      alert(
        `⚠️ Supervisión L2 requerida — ${unresolvedStops.length} dirección(es) sin coordenada confiable ` +
        `y por lo tanto EXCLUIDA(S) del plan:\n\n` + unresolvedStops.map(d => `• ${d}`).join('\n') +
        `\n\nConfirmá la dirección con el cliente y volvé a optimizar.`
      );
    }
  }

  // --------------------------------------------------------------------------
  // Controladores del Modal de JSON / Contrato de Prompts
  // --------------------------------------------------------------------------
  const modalJson = document.getElementById('modal-json');
  const btnViewJson = document.getElementById('btn-view-json');
  const btnViewContract = document.getElementById('btn-view-contract');
  const btnCloseModal = document.getElementById('btn-close-modal');
  const btnCloseModalFooter = document.getElementById('btn-close-modal-footer');
  const btnCopyModalContent = document.getElementById('btn-copy-modal-content');

  const tabJson = document.getElementById('tab-json');
  const tabSystemPrompt = document.getElementById('tab-system-prompt');
  const tabUserPrompt = document.getElementById('tab-user-prompt');

  const contentJson = document.getElementById('content-json');
  const contentSystemPrompt = document.getElementById('content-system-prompt');
  const contentUserPrompt = document.getElementById('content-user-prompt');

  let activeTab = 'json';

  function openModal(defaultTab = 'json') {
    if (!modalJson) return;
    modalJson.style.display = 'flex';
    switchTab(defaultTab);
  }

  function closeModal() {
    if (!modalJson) return;
    modalJson.style.display = 'none';
  }

  function switchTab(tabName) {
    activeTab = tabName;
    [tabJson, tabSystemPrompt, tabUserPrompt].forEach(t => t && t.classList.remove('active'));
    [contentJson, contentSystemPrompt, contentUserPrompt].forEach(c => c && (c.style.display = 'none'));

    if (tabName === 'json') {
      if (tabJson) tabJson.classList.add('active');
      if (contentJson) contentJson.style.display = 'block';
      const codeEl = document.getElementById('json-code-display');
      if (codeEl) {
        codeEl.textContent = lastAgentOutputJson 
          ? JSON.stringify(lastAgentOutputJson, null, 2) 
          : '// Ejecuta una optimización para generar la salida JSON estructurada.';
      }
    } else if (tabName === 'system') {
      if (tabSystemPrompt) tabSystemPrompt.classList.add('active');
      if (contentSystemPrompt) contentSystemPrompt.style.display = 'block';
      loadPromptFile('prompts/system_prompt.md', 'system-prompt-display');
    } else if (tabName === 'user') {
      if (tabUserPrompt) tabUserPrompt.classList.add('active');
      if (contentUserPrompt) contentUserPrompt.style.display = 'block';
      loadPromptFile('prompts/user_prompt.md', 'user-prompt-display');
    }
  }

  async function loadPromptFile(filePath, elementId) {
    const codeEl = document.getElementById(elementId);
    if (!codeEl) return;
    try {
      const res = await fetch(filePath);
      if (res.ok) {
        codeEl.textContent = await res.text();
      } else {
        codeEl.textContent = `No se pudo cargar el archivo ${filePath}`;
      }
    } catch (e) {
      codeEl.textContent = `Error al leer ${filePath}: ${e.message}`;
    }
  }

  btnViewJson?.addEventListener('click', () => openModal('json'));
  btnViewContract?.addEventListener('click', () => openModal('system'));
  btnCloseModal?.addEventListener('click', closeModal);
  btnCloseModalFooter?.addEventListener('click', closeModal);

  tabJson?.addEventListener('click', () => switchTab('json'));
  tabSystemPrompt?.addEventListener('click', () => switchTab('system'));
  tabUserPrompt?.addEventListener('click', () => switchTab('user'));

  btnCopyModalContent?.addEventListener('click', () => {
    let contentToCopy = '';
    if (activeTab === 'json') contentToCopy = document.getElementById('json-code-display')?.textContent || '';
    else if (activeTab === 'system') contentToCopy = document.getElementById('system-prompt-display')?.textContent || '';
    else if (activeTab === 'user') contentToCopy = document.getElementById('user-prompt-display')?.textContent || '';

    if (contentToCopy) {
      navigator.clipboard.writeText(contentToCopy).then(() => alert('📋 Contenido copiado al portapapeles.'));
    }
  });

  // --------------------------------------------------------------------------
  // Carga Directa de Output JSON del Agente
  // --------------------------------------------------------------------------
  async function loadAgentOutputJson(jsonObj) {
    const overlay = document.getElementById('loading-overlay');
    const loadingText = document.getElementById('loading-text');
    overlay.style.display = 'flex';
    loadingText.textContent = 'Cargando Recorrido Generado por OptiRuta-Agent...';

    lastAgentOutputJson = jsonObj;

    if (jsonObj.deposito_origen) {
      currentDepot = {
        address: jsonObj.deposito_origen.direccion || DEFAULT_DEPOT.address,
        lat: jsonObj.deposito_origen.lat || DEFAULT_DEPOT.lat,
        lng: jsonObj.deposito_origen.lng || DEFAULT_DEPOT.lng
      };
      document.getElementById('depot-address').value = currentDepot.address;
    }

    const shiftHours = parseFloat(document.getElementById('shift-hours').value) || 8;
    const maxShiftMinutes = shiftHours * 60;

    let accumulatedMinutes = 0;
    let prevPoint = currentDepot;

    // La app NO recalcula los tiempos del plan: consume los que emitió el agente.
    // (v1.0 los recomputaba con Haversine y el mapa mostraba números distintos a los
    // del JSON. Ver DECISIONES.md §3, sección "Además".)
    currentStops = jsonObj.secuencia_recorrido.map((item, idx) => {
      const stopPoint = { lat: item.lat, lng: item.lng };
      const dist = item.distancia_desde_anterior_km != null
        ? item.distancia_desde_anterior_km
        : calculateDistanceKm(prevPoint.lat, prevPoint.lng, stopPoint.lat, stopPoint.lng);
      const travelMinutes = item.viaje_desde_anterior_min != null
        ? item.viaje_desde_anterior_min
        : Math.max(3, Math.round((dist / 25) * 60));
      const serviceMinutes = item.tiempo_atencion_min || 15;
      const waitMinutes = item.espera_min || 0;

      accumulatedMinutes += travelMinutes + waitMinutes + serviceMinutes;
      prevPoint = stopPoint;

      return {
        stepNumber: item.orden || (idx + 1),
        deliveryId: item.id_entrega || `ENT-${String(idx + 1).padStart(2, '0')}`,
        trackingToken: item.tracking_token || null,
        trackingExpira: item.tracking_expira || null,
        name: item.cliente,
        address: item.direccion,
        lat: item.lat,
        lng: item.lng,
        distanceFromPrev: Number(dist).toFixed(1),
        travelMinutes: travelMinutes,
        waitMinutes: waitMinutes,
        arrivalTime: item.eta_estimado || '08:30',
        departureTime: item.salida_estimada || item.eta_estimado || '08:45',
        accumulatedMinutes: accumulatedMinutes,
        isWithinShift: accumulatedMinutes <= maxShiftMinutes,
        alerta: item.alerta || null,
        status: 'PENDING'
      };
    });

    await drawRouteOnMap(currentDepot, currentStops);
    renderResults(currentDepot, currentStops);

    renderAgentGovernanceFromJson(jsonObj);

    overlay.style.display = 'none';
  }

  function renderAgentGovernanceFromJson(jsonObj) {
    const governanceSection = document.getElementById('agent-governance-section');
    const badgeEl = document.getElementById('supervision-badge');
    const contractStatusEl = document.getElementById('agent-contract-status');
    const supervisionDescEl = document.getElementById('agent-supervision-desc');
    const alertsWrapper = document.getElementById('agent-alerts-wrapper');
    const alertsListEl = document.getElementById('agent-alerts-list');

    if (!governanceSection) return;

    const level = jsonObj.resumen_jornada?.nivel_supervision_requerido || 'L0';
    const isOk = jsonObj.resumen_jornada?.cumple_limite_8hs !== false;
    const alerts = jsonObj.alertas_y_riesgos || [];

    const ETIQUETAS_NIVEL = {
      L0: { nombre: 'Autónomo', desc: 'El agente emite y transmite la ruta sin pausa humana.' },
      L1: { nombre: 'Informativo', desc: 'Jornada cerca del límite: se notifica al despachador, sin bloqueo.' },
      L2: { nombre: 'Excepción', desc: 'Hay excepciones a resolver: el despachador confirma antes de la salida.' },
      L3: { nombre: 'Aprobación Previa', desc: 'Transmisión BLOQUEADA: requiere aprobación del despachador.' },
      L4: { nombre: 'Firma del Jefe de Logística', desc: 'Carga crítica: sin firma digital del Jefe de Logística no hay despacho.' }
    };
    const etiqueta = ETIQUETAS_NIVEL[level] || ETIQUETAS_NIVEL.L0;

    badgeEl.textContent = `${level} - ${etiqueta.nombre}`;
    badgeEl.className = `supervision-tag ${level.toLowerCase()}`;
    contractStatusEl.textContent = isOk ? '🟢 Cumple Límite 8h' : '🔴 Exceso de Jornada';
    contractStatusEl.className = isOk ? 'status-ok' : 'status-warning';

    const meta = jsonObj.meta_ejecucion || {};
    const fuente = meta.fuente_matriz_tiempos || 'no declarada';
    const noPlanificadas = (jsonObj.entregas_no_planificadas || []).length;
    supervisionDescEl.textContent =
      `${etiqueta.desc} · Tiempos: ${fuente} · Contrato validado: ${meta.contrato_validado ? 'sí' : 'no'}` +
      (noPlanificadas > 0 ? ` · ${noPlanificadas} entrega(s) sin planificar por dirección no resoluble` : '');

    if (alerts.length > 0) {
      alertsWrapper.style.display = 'block';
      alertsListEl.innerHTML = alerts.map(a => `
        <div class="agent-alert-item">
          <strong>⚠️ ${a.tipo}:</strong> ${a.descripcion}
          <div style="font-size:10px; color:#94a3b8; margin-top:2px;">💡 <b>Acción sugerida:</b> ${a.accion_sugerida}</div>
        </div>
      `).join('');
    } else {
      alertsWrapper.style.display = 'none';
      alertsListEl.innerHTML = '';
    }

    governanceSection.style.display = 'block';
  }

  // --------------------------------------------------------------------------
  // Event Listeners Principales
  // --------------------------------------------------------------------------
  document.getElementById('btn-optimize').addEventListener('click', processOptimization);
  document.getElementById('btn-toggle-live').addEventListener('click', toggleLiveSimulation);
  document.getElementById('btn-reset-live').addEventListener('click', resetLiveSimulation);

  document.getElementById('btn-load-sample').addEventListener('click', () => {
    document.getElementById('depot-address').value = DEFAULT_DEPOT.address;
    document.getElementById('address-text').value = SAMPLE_ADDRESSES.join('\n');
    processOptimization();
  });

  document.getElementById('btn-load-json-sample')?.addEventListener('click', async () => {
    try {
      const res = await fetch('output.json');
      if (res.ok) {
        const data = await res.json();
        await loadAgentOutputJson(data);
      } else {
        alert('⚠️ No se encontró output.json. Ejecuta primero "node agente.js" en la consola para generarlo.');
      }
    } catch(e) {
      alert('⚠️ Error al cargar output.json: ' + e.message);
    }
  });

  document.getElementById('btn-next-stop').addEventListener('click', () => {
    if (currentStops.length === 0) return;
    highlightStop((activeStopIndex + 1) % currentStops.length);
  });

  document.getElementById('btn-prev-stop').addEventListener('click', () => {
    if (currentStops.length === 0) return;
    highlightStop((activeStopIndex - 1 + currentStops.length) % currentStops.length);
  });

  // Lectura de Archivos
  const fileInput = document.getElementById('file-input');
  const dropZone = document.getElementById('drop-zone');

  fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) readFile(e.target.files[0]);
  });

  dropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropZone.classList.add('dragover');
  });

  dropZone.addEventListener('dragleave', () => dropZone.classList.remove('dragover'));

  dropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    dropZone.classList.remove('dragover');
    if (e.dataTransfer.files.length > 0) readFile(e.dataTransfer.files[0]);
  });

  function readFile(file) {
    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target.result;
      if (file.name.endsWith('.json') || text.trim().startsWith('{')) {
        try {
          const parsed = JSON.parse(text);
          if (parsed.secuencia_recorrido) {
            loadAgentOutputJson(parsed);
            return;
          }
        } catch(err) {}
      }
      document.getElementById('address-text').value = text;
    };
    reader.readAsText(file);
  }

  initMap();
});



