/**
 * OptiRuta 8h - Portal de Seguimiento para Clientes
 * JavaScript del Cliente Final
 */

document.addEventListener('DOMContentLoaded', () => {
  let map = null;
  let driverMarker = null;
  let destMarker = null;
  let routePolyline = null;

  // La entrega se identifica por un TOKEN opaco: ?t=<128 bits>.
  // v1.0 usaba ?stop=<índice> (enumerable: probando 0,1,2... se veían las entregas de
  // otros clientes) y además el agente emitía ?id=..., que cliente.js ni leía, así que
  // todo link caía en el índice 0. Ver DECISIONES.md §3 (hallazgo 3) y §6.
  const urlParams = new URLSearchParams(window.location.search);
  const token = urlParams.get('t');

  // Cargar estado guardado
  let routeData = null;
  try {
    const raw = localStorage.getItem('optiruta_full_route');
    if (raw) routeData = JSON.parse(raw);
  } catch (e) {}

  let targetStopIndex = -1;
  if (token && routeData && Array.isArray(routeData.stops)) {
    targetStopIndex = routeData.stops.findIndex(s => s && s.trackingToken === token);
  }

  const stopEncontrado = targetStopIndex >= 0 ? routeData.stops[targetStopIndex] : null;
  const vencimiento = stopEncontrado && stopEncontrado.trackingExpira
    ? Date.parse(stopEncontrado.trackingExpira) : null;
  const enlaceVencido = vencimiento !== null && Number.isFinite(vencimiento) && Date.now() > vencimiento;

  const parametroValido = targetStopIndex >= 0 && !enlaceVencido;
  if (targetStopIndex < 0) targetStopIndex = 0;

  function initClientMap() {
    map = L.map('client-map', { zoomControl: false }).setView([-34.5975, -58.3930], 13);

    L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', {
      maxZoom: 19,
      subdomains: 'abcd'
    }).addTo(map);

    if (parametroValido && routeData && routeData.stops && routeData.stops[targetStopIndex]) {
      renderClientView(routeData, targetStopIndex);
    } else if (enlaceVencido) {
      document.getElementById('c-name').textContent = 'Enlace de seguimiento vencido';
      document.getElementById('c-address').textContent =
        'Este enlace ya expiró. Pedí a tu proveedor uno nuevo para seguir tu entrega.';
    } else if (!parametroValido) {
      document.getElementById('c-name').textContent = 'Enlace de seguimiento inválido';
      document.getElementById('c-address').textContent =
        'Este enlace no identifica una entrega. Pedí a tu proveedor el link de seguimiento que te enviaron.';
    } else {
      document.getElementById('c-name').textContent = `Entrega #${targetStopIndex + 1}`;
      document.getElementById('c-address').textContent = 'Esperando datos de ruta del operador...';
    }

    // Escuchar actualizaciones live en tiempo real vía BroadcastChannel & localStorage
    if (typeof BroadcastChannel !== 'undefined') {
      const channel = new BroadcastChannel('optiruta_live_channel');
      channel.onmessage = (event) => {
        if (event.data && event.data.driverPos) {
          updateLiveDriverPosition(event.data.driverPos, event.data.stops);
        }
      };
    }

    window.addEventListener('storage', (e) => {
      if (e.key === 'optiruta_live_data' && e.newValue) {
        const live = JSON.parse(e.newValue);
        updateLiveDriverPosition(live.driverPos, live.stops);
      }
    });
  }

  function renderClientView(fullData, stopIdx) {
    const stop = fullData.stops[stopIdx];
    if (!stop) return;

    // 1. Actualizar Tarjeta de Información
    document.getElementById('c-name').textContent = stop.name;
    document.getElementById('c-address').textContent = stop.address;
    document.getElementById('c-eta').textContent = stop.arrivalTime;

    const remainingStops = stopIdx;
    if (stop.status === 'DELIVERED') {
      document.getElementById('c-status').textContent = '✅ ¡Entregado!';
      document.getElementById('c-status').style.color = '#10b981';
      document.getElementById('c-progress').style.width = '100%';
    } else if (remainingStops === 0) {
      document.getElementById('c-status').textContent = '🚚 ¡En camino a tu domicilio!';
      document.getElementById('c-status').style.color = '#60a5fa';
      document.getElementById('c-progress').style.width = '75%';
    } else {
      document.getElementById('c-status').textContent = `⏳ Repartidor a ${remainingStops} parada(s) de distancia`;
      document.getElementById('c-progress').style.width = `${Math.max(10, 100 - (remainingStops * 15))}%`;
    }

    // 2. Marcador de Destino del Cliente (📍)
    const clientIcon = L.divIcon({
      className: 'custom-pin-wrapper',
      html: `<div style="background:#10b981; color:white; width:36px; height:36px; border-radius:50%; display:flex; align-items:center; justify-content:center; font-size:18px; border:2px solid white; box-shadow:0 4px 12px rgba(16,185,129,0.6);">📍</div>`,
      iconSize: [36, 36],
      iconAnchor: [18, 18]
    });

    if (destMarker) map.removeLayer(destMarker);
    destMarker = L.marker([stop.lat, stop.lng], { icon: clientIcon })
      .bindPopup(`<b>Tu Domicilio:</b><br>${stop.address}`)
      .addTo(map);

    // 3. Posición Inicial del Repartidor (🚚)
    const driverPos = fullData.driverPos || fullData.depot;
    updateLiveDriverPosition(driverPos, fullData.stops);

    // Encuadrar vista
    const bounds = L.latLngBounds([[stop.lat, stop.lng], [driverPos.lat, driverPos.lng]]);
    map.fitBounds(bounds, { padding: [60, 60] });
  }

  function updateLiveDriverPosition(driverPos, stops = []) {
    if (!driverPos) return;

    if (!driverMarker) {
      const driverIcon = L.divIcon({
        className: 'custom-pin-wrapper',
        html: `<div style="background:linear-gradient(135deg, #3b82f6, #1d4ed8); color:white; width:40px; height:40px; border-radius:50%; display:flex; align-items:center; justify-content:center; font-size:20px; border:2px solid white; box-shadow:0 0 16px rgba(59,130,246,0.9);">🚚</div>`,
        iconSize: [40, 40],
        iconAnchor: [20, 20]
      });
      driverMarker = L.marker([driverPos.lat, driverPos.lng], { icon: driverIcon }).addTo(map);
    } else {
      driverMarker.setLatLng([driverPos.lat, driverPos.lng]);
    }

    // Trazar línea de guía entre el repartidor y el cliente
    if (destMarker) {
      const destLatLng = destMarker.getLatLng();
      if (routePolyline) map.removeLayer(routePolyline);
      routePolyline = L.polyline([[driverPos.lat, driverPos.lng], [destLatLng.lat, destLatLng.lng]], {
        color: '#3b82f6',
        weight: 4,
        dashArray: '6, 8',
        opacity: 0.8
      }).addTo(map);
    }

    // Actualizar estado si se pasa el array de stops
    if (stops && stops[targetStopIndex]) {
      const targetStop = stops[targetStopIndex];
      if (targetStop.status === 'DELIVERED') {
        document.getElementById('c-status').textContent = '✅ ¡Entregado!';
        document.getElementById('c-status').style.color = '#10b981';
        document.getElementById('c-progress').style.width = '100%';
      }
    }
  }

  initClientMap();
});

