/**
 * OptiRuta GPS Conductor - JavaScript de Navegación en Vivo
 * Incluye Sintetizador de Voz, GPS Real + Simulado, Turn-by-Turn y Sincronización en Tiempo Real
 */

document.addEventListener('DOMContentLoaded', () => {
  // --------------------------------------------------------------------------
  // Estado Global y Variables
  // --------------------------------------------------------------------------
  let map = null;
  let markersLayerGroup = null;
  let routeLayerGroup = null;
  let driverMarker = null;

  let currentDepot = null;
  let currentStops = [];
  let routePathPoints = [];
  let activeStopIndex = 0;

  // Estado de Localización
  let locationMode = 'SIMULATED'; // 'REAL' o 'SIMULATED'
  let watchPositionId = null;
  let isVoiceEnabled = true;

  // Estado de Simulación
  let isSimulating = false;
  let simIntervalId = null;
  let simCurrentPointIndex = 0;
  let currentSpeedKmH = 0;

  // BroadcastChannel para sincronizar con Central y Cliente
  let broadcastChannel = null;
  if (typeof BroadcastChannel !== 'undefined') {
    broadcastChannel = new BroadcastChannel('optiruta_live_channel');
  }

  // --------------------------------------------------------------------------
  // Sintetizador de Voz (Text-to-Speech)
  // --------------------------------------------------------------------------
  let lastSpokenText = '';
  function speak(text, force = false) {
    if (!isVoiceEnabled || !('speechSynthesis' in window)) return;
    if (text === lastSpokenText && !force) return;

    window.speechSynthesis.cancel(); // Cancelar anteriores para inmediatez
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'es-AR';
    utterance.rate = 1.0;
    utterance.pitch = 1.0;

    lastSpokenText = text;
    window.speechSynthesis.speak(utterance);
  }

  // --------------------------------------------------------------------------
  // Inicialización del Mapa Leaflet en Modo Oscuro (Driving HUD)
  // --------------------------------------------------------------------------
  function initMap() {
    map = L.map('driver-map', {
      zoomControl: false,
      attributionControl: false
    }).setView([-34.5975, -58.3930], 15);

    // Tiles oscuras tipo HUD para noche/conducción
    L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
      maxZoom: 19,
      subdomains: 'abcd'
    }).addTo(map);

    markersLayerGroup = L.layerGroup().addTo(map);
    routeLayerGroup = L.layerGroup().addTo(map);

    // Cargar datos desde localStorage
    loadRouteData();

    // Escuchar eventos de la central u otras pestañas
    if (broadcastChannel) {
      broadcastChannel.onmessage = (event) => {
        if (event.data && event.data.stops) {
          syncFromExternal(event.data);
        }
      };
    }
  }

  // --------------------------------------------------------------------------
  // Carga y Sincronización de Datos
  // --------------------------------------------------------------------------
  function loadRouteData() {
    const rawData = localStorage.getItem('optiruta_full_route') || localStorage.getItem('optiruta_live_data');
    if (!rawData) {
      document.getElementById('turn-text').textContent = 'No hay ruta activa. Configura una ruta en la Central (index.html).';
      return;
    }

    try {
      const data = JSON.parse(rawData);
      currentDepot = data.depot;
      currentStops = data.stops || [];
      routePathPoints = data.routePathPoints || [];

      if (currentStops.length > 0) {
        // Encontrar primera parada no entregada
        const pendingIdx = currentStops.findIndex(s => s.status !== 'DELIVERED');
        activeStopIndex = pendingIdx >= 0 ? pendingIdx : 0;

        renderRouteOnMap();
        updateHUDAndControls();
      }
    } catch (e) {
      console.error('Error al cargar ruta:', e);
    }
  }

  function syncFromExternal(data) {
    if (data.stops) currentStops = data.stops;
    if (data.depot) currentDepot = data.depot;
    if (data.routePathPoints) routePathPoints = data.routePathPoints;
    renderRouteOnMap();
    updateHUDAndControls();
  }

  function broadcastCurrentState(driverPos) {
    const liveData = {
      driverPos: driverPos,
      simIndex: simCurrentPointIndex,
      stops: currentStops,
      depot: currentDepot,
      activeStopIndex: activeStopIndex,
      timestamp: Date.now()
    };

    localStorage.setItem('optiruta_live_data', JSON.stringify(liveData));
    localStorage.setItem('optiruta_full_route', JSON.stringify({
      ...liveData,
      routePathPoints: routePathPoints
    }));

    if (broadcastChannel) {
      broadcastChannel.postMessage(liveData);
    }
  }

  // --------------------------------------------------------------------------
  // Renderizado en Mapa
  // --------------------------------------------------------------------------
  function renderRouteOnMap() {
    markersLayerGroup.clearLayers();
    routeLayerGroup.clearLayers();

    if (!currentDepot) return;

    // Origen
    const depotIcon = L.divIcon({
      className: 'custom-pin-wrapper',
      html: `<div class="custom-pin depot-pin">🏠</div>`,
      iconSize: [36, 36],
      iconAnchor: [18, 18]
    });
    L.marker([currentDepot.lat, currentDepot.lng], { icon: depotIcon })
      .bindPopup(`<b>🏠 Origen / Depósito</b><br>${currentDepot.address}`)
      .addTo(markersLayerGroup);

    // Paradas
    currentStops.forEach((stop, index) => {
      let pinClass = 'on-time-pin';
      let iconSymbol = stop.stepNumber;

      if (stop.status === 'DELIVERED') {
        pinClass = 'completed-pin';
        iconSymbol = '✓';
      } else if (stop.status === 'INCIDENTE') {
        pinClass = 'exceeded-pin';
        iconSymbol = '⚠️';
      } else if (index === activeStopIndex) {
        pinClass = 'active-pin-hud';
      }

      const customIcon = L.divIcon({
        className: 'custom-pin-wrapper',
        html: `<div class="custom-pin ${pinClass}">${iconSymbol}</div>`,
        iconSize: [36, 36],
        iconAnchor: [18, 18]
      });

      const marker = L.marker([stop.lat, stop.lng], { icon: customIcon }).addTo(markersLayerGroup);
      marker.bindPopup(`<b>Parada #${stop.stepNumber}: ${stop.name}</b><br>${stop.address}`);
      marker.on('click', () => selectStop(index));
    });

    // Línea de Ruta
    if (routePathPoints.length > 0) {
      const latLngs = routePathPoints.map(p => [p.lat, p.lng]);
      L.polyline(latLngs, { color: '#3b82f6', weight: 6, opacity: 0.85 }).addTo(routeLayerGroup);
    }
  }

  function updateDriverMarker(lat, lng, heading = 0) {
    if (!driverMarker) {
      const driverIcon = L.divIcon({
        className: 'custom-pin-wrapper',
        html: `<div class="custom-pin driver-pin" id="driver-icon-inner" style="transform: rotate(${heading}deg);">🚚</div>`,
        iconSize: [42, 42],
        iconAnchor: [21, 21]
      });
      driverMarker = L.marker([lat, lng], { icon: driverIcon }).addTo(markersLayerGroup);
    } else {
      driverMarker.setLatLng([lat, lng]);
      const inner = document.getElementById('driver-icon-inner');
      if (inner) inner.style.transform = `rotate(${heading}deg)`;
    }
  }

  // --------------------------------------------------------------------------
  // Navegación Turn-by-Turn y Banner HUD
  // --------------------------------------------------------------------------
  function calculateDistanceKm(lat1, lon1, lat2, lon2) {
    const R = 6371;
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
              Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * 
              Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
  }

  function calculateBearing(lat1, lon1, lat2, lon2) {
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const y = Math.sin(dLon) * Math.cos(lat2 * Math.PI / 180);
    const x = Math.cos(lat1 * Math.PI / 180) * Math.sin(lat2 * Math.PI / 180) -
              Math.sin(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.cos(dLon);
    let brng = Math.atan2(y, x) * 180 / Math.PI;
    return (brng + 360) % 360;
  }

  function getDirectionIconAndText(bearing, prevBearing = 0) {
    const diff = (bearing - prevBearing + 360) % 360;
    if (diff > 45 && diff <= 135) return { icon: '➡️', text: 'Gira a la derecha' };
    if (diff > 135 && diff <= 225) return { icon: '⬇️', text: 'Giro en U' };
    if (diff > 225 && diff <= 315) return { icon: '⬅️', text: 'Gira a la izquierda' };
    return { icon: '⬆️', text: 'Continúa derecho' };
  }

  function updateGPSPosition(currentPos, speedKmH = 0) {
    currentSpeedKmH = speedKmH;
    document.getElementById('hud-speed').textContent = Math.round(speedKmH);

    const targetStop = currentStops[activeStopIndex];
    if (!targetStop) return;

    const distKm = calculateDistanceKm(currentPos.lat, currentPos.lng, targetStop.lat, targetStop.lng);
    const distMeters = Math.round(distKm * 1000);
    const bearing = calculateBearing(currentPos.lat, currentPos.lng, targetStop.lat, targetStop.lng);

    updateDriverMarker(currentPos.lat, currentPos.lng, bearing);

    // Formatear distancia HUD
    const distFormatted = distMeters >= 1000 ? `${(distKm).toFixed(1)} km` : `${distMeters} m`;
    document.getElementById('turn-distance').textContent = distFormatted;

    // Indicaciones y Sintetizador de Voz
    const turnInfo = getDirectionIconAndText(bearing);
    document.getElementById('turn-icon').textContent = turnInfo.icon;

    let instructionText = `${turnInfo.text} hacia ${targetStop.name}`;
    document.getElementById('turn-text').textContent = instructionText;

    // Avisos de voz por proximidad
    if (distMeters <= 50 && targetStop.status !== 'DELIVERED') {
      speak(`Has llegado a tu destino: ${targetStop.name}.`, true);
    } else if (distMeters <= 250 && distMeters > 200) {
      speak(`En 200 metros llegarás a ${targetStop.name}`);
    } else if (distMeters <= 800 && distMeters > 750) {
      speak(`A 800 metros, ${instructionText}`);
    }

    // Centrar mapa si está activo el seguimiento
    map.panTo([currentPos.lat, currentPos.lng], { animate: true });

    // Transmitir posición a Central y Cliente
    broadcastCurrentState(currentPos);
  }

  // --------------------------------------------------------------------------
  // Modos de Localización: GPS Real vs Simulación
  // --------------------------------------------------------------------------
  function setLocationMode(mode) {
    locationMode = mode;
    const realBtn = document.getElementById('mode-real-gps');
    const simBtn = document.getElementById('mode-sim-gps');
    const simPanel = document.getElementById('sim-controls-panel');
    const indicator = document.getElementById('gps-status-indicator');

    if (mode === 'REAL') {
      realBtn.classList.add('active');
      simBtn.classList.remove('active');
      simPanel.style.display = 'none';
      stopSimulation();
      startRealGPS();
      indicator.className = 'gps-status-dot green';
      speak('Modo GPS Real activado.');
    } else {
      simBtn.classList.add('active');
      realBtn.classList.remove('active');
      simPanel.style.display = 'block';
      stopRealGPS();
      indicator.className = 'gps-status-dot orange';
      speak('Modo Simulado activado.');
    }
  }

  function startRealGPS() {
    if (!navigator.geolocation) {
      alert('Tu dispositivo o navegador no soporta la API de Geolocalización GPS.');
      setLocationMode('SIMULATED');
      return;
    }

    watchPositionId = navigator.geolocation.watchPosition(
      (position) => {
        const speed = (position.coords.speed || 0) * 3.6; // m/s a km/h
        const pos = {
          lat: position.coords.latitude,
          lng: position.coords.longitude
        };
        updateGPSPosition(pos, speed);
      },
      (error) => {
        console.warn('Error GPS:', error);
        document.getElementById('turn-text').textContent = '⚠️ Buscando señal GPS...';
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 1000 }
    );
  }

  function stopRealGPS() {
    if (watchPositionId !== null) {
      navigator.geolocation.clearWatch(watchPositionId);
      watchPositionId = null;
    }
  }

  // --------------------------------------------------------------------------
  // Simulación
  // --------------------------------------------------------------------------
  function startSimulation() {
    if (routePathPoints.length === 0) {
      alert('No hay una ruta trazada para simular. Cárgala desde la Central.');
      return;
    }

    isSimulating = true;
    const speedMultiplier = parseInt(document.getElementById('sim-speed-select').value) || 5;
    const intervalMs = Math.max(40, 300 / speedMultiplier);

    const btnPlay = document.getElementById('btn-sim-play');
    btnPlay.textContent = '⏸ Pausar Simulación';
    btnPlay.className = 'btn btn-secondary btn-sm';

    clearInterval(simIntervalId);
    simIntervalId = setInterval(() => {
      if (simCurrentPointIndex >= routePathPoints.length) {
        stopSimulation();
        speak('Simulación de recorrido completada.');
        return;
      }

      const currentPos = routePathPoints[simCurrentPointIndex];
      const simSpeed = 30 * (speedMultiplier / 5); // Simulamos km/h
      updateGPSPosition(currentPos, simSpeed);

      simCurrentPointIndex++;
    }, intervalMs);
  }

  function stopSimulation() {
    isSimulating = false;
    clearInterval(simIntervalId);
    const btnPlay = document.getElementById('btn-sim-play');
    if (btnPlay) {
      btnPlay.textContent = '▶ Iniciar Simulación';
      btnPlay.className = 'btn btn-success btn-sm';
    }
  }

  // --------------------------------------------------------------------------
  // Gestión de Paradas y Acciones del Conductor
  // --------------------------------------------------------------------------
  function selectStop(index) {
    if (index < 0 || index >= currentStops.length) return;
    activeStopIndex = index;
    updateHUDAndControls();
    renderRouteOnMap();

    const stop = currentStops[index];
    map.flyTo([stop.lat, stop.lng], 16, { duration: 0.8 });
  }

  function updateHUDAndControls() {
    if (currentStops.length === 0) return;

    const stop = currentStops[activeStopIndex];
    document.getElementById('sub-next-stop').textContent = `#${stop.stepNumber} ${stop.name}`;
    document.getElementById('sub-eta').textContent = stop.arrivalTime || '--:--';

    const completedCount = currentStops.filter(s => s.status === 'DELIVERED').length;
    document.getElementById('sub-progress').textContent = `${completedCount}/${currentStops.length}`;

    // Actualizar Card Inferior
    document.getElementById('stop-number-badge').textContent = `#${stop.stepNumber}`;
    document.getElementById('stop-client-name').textContent = stop.name;
    document.getElementById('stop-address-text').textContent = stop.address;

    const chip = document.getElementById('stop-status-chip');
    if (stop.status === 'DELIVERED') {
      chip.textContent = 'ENTREGADO';
      chip.className = 'status-chip delivered';
    } else if (stop.status === 'INCIDENTE') {
      chip.textContent = 'INCIDENCIA';
      chip.className = 'status-chip incident';
    } else {
      chip.textContent = 'PENDIENTE';
      chip.className = 'status-chip pending';
    }

    renderDrawerStopsList();
  }

  function confirmCurrentDelivery() {
    if (currentStops.length === 0) return;
    const stop = currentStops[activeStopIndex];
    stop.status = 'DELIVERED';

    speak(`Entrega ${stop.stepNumber} completada en ${stop.name}.`);

    // Siguiente parada
    const nextIdx = currentStops.findIndex((s, i) => i > activeStopIndex && s.status !== 'DELIVERED');
    if (nextIdx >= 0) {
      activeStopIndex = nextIdx;
      speak(`Siguiente destino: ${currentStops[nextIdx].name}`);
    } else {
      speak('¡Felicidades! Has completado todas las entregas del turno.');
    }

    updateHUDAndControls();
    renderRouteOnMap();

    const driverPos = driverMarker ? driverMarker.getLatLng() : { lat: stop.lat, lng: stop.lng };
    broadcastCurrentState(driverPos);
  }

  function openExternalMaps() {
    if (currentStops.length === 0) return;
    const stop = currentStops[activeStopIndex];

    // URL Google Maps para navegación turn-by-turn nativa
    const gmapsUrl = `https://www.google.com/maps/dir/?api=1&destination=${stop.lat},${stop.lng}&travelmode=driving`;
    window.open(gmapsUrl, '_blank');
  }

  function callClient() {
    if (currentStops.length === 0) return;
    const stop = currentStops[activeStopIndex];
    alert(`📞 Llamando a ${stop.name} (${stop.address})\nEn un entorno real de produção, esto inicia la llamada telefónica o WhatsApp al cliente.`);
  }

  function reportIncident() {
    if (currentStops.length === 0) return;
    const stop = currentStops[activeStopIndex];

    const motive = prompt(`⚠️ Reportar Novedad/Incidencia para "${stop.name}":\n\n1. Cliente ausente\n2. Dirección no encontrada\n3. Tráfico / Acceso bloqueado\n4. Rechazado\n\nEscribe el motivo o número:`, "Cliente ausente");

    if (motive) {
      stop.status = 'INCIDENTE';
      stop.incidentNote = motive;
      speak(`Incidencia registrada para ${stop.name}.`);

      updateHUDAndControls();
      renderRouteOnMap();

      const driverPos = driverMarker ? driverMarker.getLatLng() : { lat: stop.lat, lng: stop.lng };
      broadcastCurrentState(driverPos);
    }
  }

  // --------------------------------------------------------------------------
  // Drawer de Entregas (Hoja de Ruta)
  // --------------------------------------------------------------------------
  function renderDrawerStopsList() {
    const container = document.getElementById('drawer-stops-list');
    container.innerHTML = '';

    currentStops.forEach((stop, index) => {
      const item = document.createElement('div');
      const isCurrent = index === activeStopIndex;
      item.className = `drawer-stop-item ${isCurrent ? 'active' : ''} ${stop.status === 'DELIVERED' ? 'completed' : ''}`;

      item.innerHTML = `
        <div class="drawer-stop-badge">${stop.stepNumber}</div>
        <div class="drawer-stop-details">
          <strong>${stop.name}</strong>
          <p>${stop.address}</p>
          <span class="drawer-stop-time">⏰ LLegada est.: ${stop.arrivalTime}</span>
        </div>
        <div class="drawer-stop-status">
          ${stop.status === 'DELIVERED' ? '✅' : stop.status === 'INCIDENTE' ? '⚠️' : '⏳'}
        </div>
      `;

      item.addEventListener('click', () => {
        selectStop(index);
        closeDrawer();
      });

      container.appendChild(item);
    });
  }

  function openDrawer() {
    document.getElementById('drawer-overlay').classList.add('open');
  }

  function closeDrawer() {
    document.getElementById('drawer-overlay').classList.remove('open');
  }

  // --------------------------------------------------------------------------
  // Listeners de Eventos
  // --------------------------------------------------------------------------
  document.getElementById('mode-real-gps').addEventListener('click', () => setLocationMode('REAL'));
  document.getElementById('mode-sim-gps').addEventListener('click', () => setLocationMode('SIMULATED'));

  document.getElementById('btn-sim-play').addEventListener('click', () => {
    if (isSimulating) {
      stopSimulation();
    } else {
      startSimulation();
    }
  });

  document.getElementById('btn-sim-next').addEventListener('click', () => {
    if (activeStopIndex < currentStops.length - 1) {
      selectStop(activeStopIndex + 1);
    }
  });

  document.getElementById('btn-sim-prev').addEventListener('click', () => {
    if (activeStopIndex > 0) {
      selectStop(activeStopIndex - 1);
    }
  });

  document.getElementById('btn-deliver-current').addEventListener('click', confirmCurrentDelivery);
  document.getElementById('btn-open-waze').addEventListener('click', openExternalMaps);
  document.getElementById('btn-call-client').addEventListener('click', callClient);
  document.getElementById('btn-report-issue').addEventListener('click', reportIncident);

  document.getElementById('btn-recenter').addEventListener('click', () => {
    if (driverMarker) {
      map.flyTo(driverMarker.getLatLng(), 17, { duration: 0.8 });
    }
  });

  document.getElementById('btn-toggle-voice').addEventListener('click', () => {
    isVoiceEnabled = !isVoiceEnabled;
    const btn = document.getElementById('btn-toggle-voice');
    btn.className = `fab-btn ${isVoiceEnabled ? 'voice-on' : 'voice-off'}`;
    btn.textContent = isVoiceEnabled ? '🔊' : '🔇';
    speak(isVoiceEnabled ? 'Voz activada' : 'Voz desactivada', true);
  });

  document.getElementById('btn-toggle-drawer').addEventListener('click', openDrawer);
  document.getElementById('btn-close-drawer').addEventListener('click', closeDrawer);
  document.getElementById('drawer-overlay').addEventListener('click', (e) => {
    if (e.target.id === 'drawer-overlay') closeDrawer();
  });

  // Inicializar
  initMap();
  setLocationMode('SIMULATED');
});

