/* ==========================================================================
   OptiRuta 8h - Estilos Modernos, Live Tracking & Vista Cliente
   ========================================================================== */

:root {
  --bg-main: #0f172a;
  --bg-sidebar: #1e293b;
  --bg-card: #334155;
  --bg-card-hover: #475569;

  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dark: #0f172a;

  --primary: #3b82f6;
  --primary-hover: #2563eb;
  --success: #10b981;
  --success-bg: rgba(16, 185, 129, 0.15);
  --warning: #f59e0b;
  --warning-bg: rgba(245, 158, 11, 0.15);
  --danger: #ef4444;

  --border-color: rgba(255, 255, 255, 0.1);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;

  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.2);
  --shadow-md: 0 4px 20px rgba(0, 0, 0, 0.3);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
}

body, html {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg-main);
  color: var(--text-main);
}

.app-container {
  display: flex;
  width: 100vw;
  height: 100vh;
}

/* --------------------------------------------------------------------------
   Sidebar Layout & Components
   -------------------------------------------------------------------------- */
.sidebar {
  width: 460px;
  min-width: 380px;
  height: 100%;
  background-color: var(--bg-sidebar);
  border-right: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  z-index: 10;
  box-shadow: var(--shadow-md);
}

.app-header {
  padding: 20px 24px;
  border-bottom: 1px solid var(--border-color);
  background: rgba(15, 23, 42, 0.5);
  backdrop-filter: blur(8px);
}

.logo-area {
  display: flex;
  align-items: center;
  gap: 14px;
}

.logo-icon {
  width: 44px;
  height: 44px;
  background: linear-gradient(135deg, #3b82f6, #1d4ed8);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  box-shadow: 0 4px 12px rgba(59, 130, 246, 0.4);
}

.app-header h1 {
  font-size: 19px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-main);
}

.app-header p {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: 2px;
}

.sidebar-content {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.sidebar-content::-webkit-scrollbar {
  width: 6px;
}
.sidebar-content::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 4px;
}

/* --------------------------------------------------------------------------
   Cards & Form Controls
   -------------------------------------------------------------------------- */
.card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.card h2 {
  font-size: 15px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 10px;
  color: #e2e8f0;
}

.step-num {
  width: 24px;
  height: 24px;
  background-color: var(--primary);
  color: white;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-row {
  display: flex;
  gap: 12px;
}

.form-group.half {
  flex: 1;
}

label {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-muted);
}

input[type="text"],
input[type="number"],
input[type="time"],
textarea, select {
  width: 100%;
  padding: 10px 12px;
  background-color: rgba(15, 23, 42, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: var(--radius-sm);
  color: var(--text-main);
  font-size: 13px;
  outline: none;
  transition: all 0.2s ease;
}

input:focus, textarea:focus, select:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.25);
}

.input-with-icon {
  position: relative;
  display: flex;
  align-items: center;
}

.input-with-icon .icon {
  position: absolute;
  left: 10px;
  font-size: 14px;
}

.input-with-icon input {
  padding-left: 32px;
}

/* Dropzone */
.drop-zone {
  border: 2px dashed rgba(255, 255, 255, 0.2);
  border-radius: var(--radius-md);
  padding: 20px;
  text-align: center;
  background-color: rgba(15, 23, 42, 0.3);
  transition: all 0.2s ease;
  cursor: pointer;
}

.drop-zone:hover, .drop-zone.dragover {
  border-color: var(--primary);
  background-color: rgba(59, 130, 246, 0.1);
}

.drop-icon {
  font-size: 32px;
  margin-bottom: 6px;
}

.drop-text {
  font-size: 13px;
  color: #cbd5e1;
}

.drop-subtext {
  font-size: 11px;
  color: var(--text-muted);
  margin-bottom: 12px;
}

#file-input {
  display: none;
}

/* Buttons */
.btn {
  padding: 10px 16px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  font-weight: 600;
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: all 0.2s ease;
}

.btn-primary {
  background: linear-gradient(135deg, #3b82f6, #2563eb);
  color: white;
  box-shadow: 0 4px 14px rgba(37, 99, 235, 0.4);
}

.btn-primary:hover {
  background: linear-gradient(135deg, #2563eb, #1d4ed8);
  transform: translateY(-1px);
}

.btn-success {
  background: linear-gradient(135deg, #10b981, #059669);
  color: white;
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.4);
}

.btn-success:hover {
  background: linear-gradient(135deg, #059669, #047857);
}

.btn-secondary {
  background-color: rgba(255, 255, 255, 0.1);
  color: #e2e8f0;
}

.btn-secondary:hover {
  background-color: rgba(255, 255, 255, 0.2);
}

.btn-outline {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #e2e8f0;
}

.btn-outline:hover {
  border-color: var(--primary);
  color: var(--primary);
  background-color: rgba(59, 130, 246, 0.1);
}

.btn-share {
  background: rgba(59, 130, 246, 0.2);
  border: 1px solid rgba(59, 130, 246, 0.5);
  color: #93c5fd;
  font-size: 11px;
  padding: 4px 8px;
  border-radius: 4px;
}

.btn-share:hover {
  background: var(--primary);
  color: white;
}

.btn-block {
  width: 100%;
}

.btn-lg {
  padding: 14px 20px;
  font-size: 14px;
}

.btn-sm {
  padding: 6px 12px;
  font-size: 12px;
}

.select-sm {
  padding: 6px 8px;
  font-size: 12px;
  width: auto;
}

.btn-icon {
  width: 36px;
  height: 36px;
  padding: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.1);
  color: white;
  font-size: 14px;
}

.btn-icon:hover {
  background: var(--primary);
}

.btn-highlight {
  background: var(--primary);
  box-shadow: 0 0 12px rgba(59, 130, 246, 0.6);
}

/* --------------------------------------------------------------------------
   Live Simulation Controls
   -------------------------------------------------------------------------- */
.live-simulation-bar {
  background: rgba(15, 23, 42, 0.7);
  padding: 12px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(16, 185, 129, 0.4);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.live-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: #6ee7b7;
}

.live-pulse-dot {
  width: 10px;
  height: 10px;
  background-color: #10b981;
  border-radius: 50%;
  animation: pulse-dot 1.5s infinite;
}

@keyframes pulse-dot {
  0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.7); }
  70% { transform: scale(1); box-shadow: 0 0 0 8px rgba(16, 185, 129, 0); }
  100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(16, 185, 129, 0); }
}

.live-controls {
  display: flex;
  gap: 8px;
  align-items: center;
}

/* --------------------------------------------------------------------------
   Results Section & Tour Controls
   -------------------------------------------------------------------------- */
.results-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.results-badge {
  font-size: 12px;
  padding: 4px 10px;
  background-color: rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  color: #cbd5e1;
}

.tour-controls {
  background: rgba(15, 23, 42, 0.7);
  padding: 12px 14px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: space-between;
  border: 1px solid var(--primary);
}

.tour-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-width: 220px;
}

.tour-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--primary);
  font-weight: 700;
}

#tour-current-name {
  font-size: 13px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tour-buttons {
  display: flex;
  gap: 8px;
}

/* Metrics Grid */
.stats-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.stat-box {
  background-color: rgba(15, 23, 42, 0.5);
  border: 1px solid var(--border-color);
  padding: 10px;
  border-radius: var(--radius-sm);
  text-align: center;
}

.stat-box.green {
  border-color: rgba(16, 185, 129, 0.4);
  background-color: var(--success-bg);
}

.stat-box.orange {
  border-color: rgba(245, 158, 11, 0.4);
  background-color: var(--warning-bg);
}

.stat-value {
  font-size: 18px;
  font-weight: 700;
  color: white;
}

.stat-box.green .stat-value { color: var(--success); }
.stat-box.orange .stat-value { color: var(--warning); }

.stat-label {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 2px;
}

/* Stops List */
.stops-wrapper h3 {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin: 12px 0 8px 0;
}

.stops-wrapper h3.exceeded-title {
  color: var(--warning);
  margin-top: 20px;
}

.stops-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.stop-card {
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 12px;
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  transition: all 0.2s ease;
  position: relative;
}

.stop-card:hover {
  background: var(--bg-card-hover);
  border-color: var(--primary);
}

.stop-card.active {
  border-color: var(--primary);
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.3);
  background: rgba(59, 130, 246, 0.15);
}

.stop-card.completed {
  opacity: 0.65;
  border-color: rgba(16, 185, 129, 0.3);
  background: rgba(16, 185, 129, 0.05);
}

.stop-badge {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background-color: var(--success);
  color: white;
  font-size: 13px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.stop-card.exceeded .stop-badge {
  background-color: var(--warning);
}

.stop-details {
  flex: 1;
  min-width: 0;
}

.stop-title {
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.stop-sub {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.stop-actions {
  margin-top: 6px;
}

.stop-time {
  text-align: right;
  flex-shrink: 0;
}

.stop-time .arrival {
  font-size: 13px;
  font-weight: 700;
  color: var(--success);
}

.stop-card.exceeded .stop-time .arrival {
  color: var(--warning);
}

.stop-time .duration {
  font-size: 10px;
  color: var(--text-muted);
}

/* --------------------------------------------------------------------------
   Map Area & Custom Leaflet Elements
   -------------------------------------------------------------------------- */
.map-container {
  flex: 1;
  position: relative;
  height: 100%;
}

#map {
  width: 100%;
  height: 100%;
  background-color: #0f172a;
}

/* Map Legend */
.map-legend {
  position: absolute;
  bottom: 24px;
  right: 24px;
  background: rgba(15, 23, 42, 0.85);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border-color);
  padding: 12px 16px;
  border-radius: var(--radius-md);
  z-index: 1000;
  display: flex;
  gap: 16px;
  box-shadow: var(--shadow-md);
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--text-main);
}

.legend-badge {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  color: white;
}

.legend-badge.depot { background: #ef4444; }
.legend-badge.driver { background: #3b82f6; }
.legend-badge.on-time { background: #10b981; }
.legend-badge.exceeded { background: #f59e0b; }

/* Custom Leaflet Pins */
.custom-pin {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  color: white;
  font-weight: 700;
  font-size: 14px;
  border: 2px solid white;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.4);
  transition: transform 0.2s ease;
}

.custom-pin.depot-pin {
  background: #ef4444;
  border-color: #fca5a5;
  font-size: 16px;
}

.custom-pin.driver-pin {
  background: linear-gradient(135deg, #3b82f6, #1d4ed8);
  border-color: #93c5fd;
  font-size: 18px;
  box-shadow: 0 0 16px rgba(59, 130, 246, 0.8);
  animation: pulse-driver 1.5s infinite;
}

@keyframes pulse-driver {
  0% { transform: scale(1); box-shadow: 0 0 0 0 rgba(59, 130, 246, 0.8); }
  70% { transform: scale(1.15); box-shadow: 0 0 0 12px rgba(59, 130, 246, 0); }
  100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(59, 130, 246, 0); }
}

.custom-pin.on-time-pin {
  background: #10b981;
  border-color: #6ee7b7;
}

.custom-pin.exceeded-pin {
  background: #f59e0b;
  border-color: #fde68a;
}

.custom-pin.active-pin {
  transform: scale(1.3);
  box-shadow: 0 0 20px rgba(59, 130, 246, 0.9);
  border-color: #60a5fa;
  animation: pulse-pin 1.5s infinite;
}

@keyframes pulse-pin {
  0% { box-shadow: 0 0 0 0 rgba(59, 130, 246, 0.7); }
  70% { box-shadow: 0 0 0 14px rgba(59, 130, 246, 0); }
  100% { box-shadow: 0 0 0 0 rgba(59, 130, 246, 0); }
}

/* Loading Overlay */
.loading-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(6px);
  z-index: 2000;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
}

.spinner {
  width: 48px;
  height: 48px;
  border: 4px solid rgba(255, 255, 255, 0.1);
  border-top-color: var(--primary);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.loading-text {
  font-size: 15px;
  font-weight: 500;
  color: #e2e8f0;
}

/* Responsive */
@media (max-width: 900px) {
  .app-container {
    flex-direction: column;
  }
  .sidebar {
    width: 100%;
    min-width: 100%;
    height: 50vh;
  }
  .map-container {
    height: 50vh;
  }
}

/* --------------------------------------------------------------------------
