/**
 * validador.js — Validador de contrato (subconjunto de JSON Schema draft-07)
 *
 * El contrato NO se duplica en el código: este validador extrae el JSON Schema
 * directamente del bloque ```json de prompts/system_prompt.md y valida contra él.
 * Si el contrato y la salida se separan, la ejecución falla.
 *
 * Uso standalone:
 *   node validador.js output.json
 *
 * Soporta: type (incl. array de tipos), required, properties, items, enum,
 * additionalProperties=false. Es deliberadamente chico: no necesitamos más.
 */

const fs = require('fs');
const path = require('path');

const SYSTEM_PROMPT_PATH = path.join(__dirname, 'prompts', 'system_prompt.md');

/** Extrae el JSON Schema embebido en el System Prompt (el contrato es la fuente de verdad). */
function cargarSchemaDelContrato(promptPath = SYSTEM_PROMPT_PATH) {
  const md = fs.readFileSync(promptPath, 'utf-8');
  const bloques = [...md.matchAll(/```json\s*\n([\s\S]*?)\n```/g)].map(m => m[1]);
  for (const bloque of bloques) {
    try {
      const obj = JSON.parse(bloque);
      if (obj && obj.$schema && obj.properties) return obj;
    } catch (e) {
      // el bloque no era el schema; seguimos buscando
    }
  }
  throw new Error(`No se encontró un JSON Schema válido en ${promptPath}`);
}

function tipoDe(valor) {
  if (valor === null) return 'null';
  if (Array.isArray(valor)) return 'array';
  if (Number.isInteger(valor)) return 'integer';
  return typeof valor === 'number' ? 'number' : typeof valor;
}

function tipoCompatible(valor, tipoEsperado) {
  const tipos = Array.isArray(tipoEsperado) ? tipoEsperado : [tipoEsperado];
  const real = tipoDe(valor);
  return tipos.some(t => t === real || (t === 'number' && real === 'integer'));
}

function validarNodo(valor, schema, ruta, errores) {
  if (!schema || typeof schema !== 'object') return;

  if (schema.type && !tipoCompatible(valor, schema.type)) {
    errores.push(`${ruta}: se esperaba ${JSON.stringify(schema.type)} y llegó ${tipoDe(valor)}`);
    return;
  }

  if (schema.enum && !schema.enum.includes(valor)) {
    errores.push(`${ruta}: "${valor}" no pertenece a ${JSON.stringify(schema.enum)}`);
  }

  if (tipoDe(valor) === 'object') {
    for (const req of schema.required || []) {
      if (!(req in valor)) errores.push(`${ruta}.${req}: campo obligatorio ausente`);
    }
    for (const [clave, sub] of Object.entries(schema.properties || {})) {
      if (clave in valor) validarNodo(valor[clave], sub, `${ruta}.${clave}`, errores);
    }
    if (schema.additionalProperties === false) {
      const permitidas = Object.keys(schema.properties || {});
      for (const clave of Object.keys(valor)) {
        if (!permitidas.includes(clave)) errores.push(`${ruta}.${clave}: propiedad no declarada en el contrato`);
      }
    }
  }

  if (tipoDe(valor) === 'array' && schema.items) {
    valor.forEach((item, i) => validarNodo(item, schema.items, `${ruta}[${i}]`, errores));
  }
}

/** Devuelve { valido: boolean, errores: string[] }. */
function validarContraContrato(salida, promptPath) {
  const schema = cargarSchemaDelContrato(promptPath);
  const errores = [];
  validarNodo(salida, schema, 'raiz', errores);
  return { valido: errores.length === 0, errores };
}

module.exports = { validarContraContrato, cargarSchemaDelContrato };

if (require.main === module) {
  const archivo = process.argv[2] || 'output.json';
  const salida = JSON.parse(fs.readFileSync(archivo, 'utf-8'));
  const { valido, errores } = validarContraContrato(salida);
  if (valido) {
    console.log(`✅ ${archivo} cumple el contrato de prompts/system_prompt.md`);
  } else {
    console.error(`❌ ${archivo} NO cumple el contrato:`);
    errores.forEach(e => console.error(`   - ${e}`));
    process.exit(1);
  }
}

